import React, { useEffect, useState } from 'react';
import { CuisineCategory, Dish, ThemeType, SuitableForTag } from '../types';
import { 
  ChevronLeft, ChevronRight, Home, Settings, Flame, Beef, Coffee, 
  Sun, Moon, Zap, Activity, Feather, Wheat, Loader2, ArrowRight
} from 'lucide-react';

interface ClientViewProps {
  categories: CuisineCategory[];
  dishes: Dish[];
  viewState: {
    view: 'menu-overview' | 'dish-viewer';
    currentCategory: string | null;
    currentDishIndex: number;
  };
  setViewState: React.Dispatch<React.SetStateAction<any>>;
  theme: ThemeType;
  appTitle: string;
  appSubtitle: string;
  isOffline?: boolean;
  onOpenSettings?: () => void;
}

const TAG_CONFIG: Record<SuitableForTag, { icon: React.ElementType, className: string }> = {
    'breakfast': { icon: Coffee, className: 'bg-amber-50 text-amber-800 border-amber-100' },
    'lunch': { icon: Sun, className: 'bg-orange-50 text-orange-800 border-orange-100' },
    'dinner': { icon: Moon, className: 'bg-indigo-50 text-indigo-800 border-indigo-100' },
    'pre-workout': { icon: Zap, className: 'bg-yellow-50 text-yellow-800 border-yellow-100' },
    'post-workout': { icon: Activity, className: 'bg-rose-50 text-rose-800 border-rose-100' },
    'light-meal': { icon: Feather, className: 'bg-emerald-50 text-emerald-800 border-emerald-100' },
    'high-protein': { icon: Beef, className: 'bg-red-50 text-red-800 border-red-100' },
    'low-carb': { icon: Wheat, className: 'bg-green-50 text-green-800 border-green-100' },
};

const ImageWithFallback = ({ src, alt, className }: { src: string; alt: string; className: string }) => {
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(true);

  return (
    <div className={`relative w-full h-full bg-[#1A1A1A] overflow-hidden ${className}`}>
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center bg-[#1A1A1A] z-10">
          <Loader2 className="animate-spin text-gray-700" size={32} />
        </div>
      )}
      <img
        src={error ? 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&q=80&w=800' : src}
        alt={alt}
        className={`w-full h-full object-cover transition-all duration-1000 ${loading ? 'opacity-0 scale-110' : 'opacity-100 scale-100'}`}
        onLoad={() => setLoading(false)}
        onError={() => {
          setError(true);
          setLoading(false);
        }}
      />
    </div>
  );
};

export const ClientView: React.FC<ClientViewProps> = ({ categories, dishes, viewState, setViewState, theme, appTitle, appSubtitle, onOpenSettings }) => {
