  const handleNav = (direction: 'prev' | 'next') => {
    const categoryDishes = dishes.filter(d => d.categoryId === viewState.currentCategory);
    let nextIndex = viewState.currentDishIndex + (direction === 'next' ? 1 : -1);
    if (nextIndex < 0) nextIndex = categoryDishes.length - 1;
    if (nextIndex >= categoryDishes.length) nextIndex = 0;
    setViewState((prev: any) => ({ ...prev, currentDishIndex: nextIndex }));
  };

  const currentCategoryDishes = dishes.filter(d => d.categoryId === viewState.currentCategory);
  const currentDish = currentCategoryDishes[viewState.currentDishIndex];

  if (viewState.view === 'menu-overview') {
    return (
      <div className="min-h-screen bg-[#0F0F0F] text-white">
        <div className="max-w-7xl mx-auto px-6 py-16 md:py-32">
          {/* Hero Header Section */}
          <header className="mb-20 max-w-3xl animate-slide-up">
            <h1 className="text-6xl md:text-8xl font-thin tracking-tight mb-8 leading-tight">
              Select Your <span className="text-gold italic font-['Playfair_Display'] font-normal">Experience</span>
            </h1>
            <div className="w-24 h-0.5 bg-gold mb-8"></div>
            <p className="text-gray-400 text-lg md:text-xl font-light leading-relaxed max-w-2xl">
              {appSubtitle || "Curated culinary journeys designed for the discerning palate. From the sun-drenched coasts of the Mediterranean to the avant-garde kitchens of Paris."}
            </p>
          </header>

          {/* Experience Cards Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 md:gap-12">
            {categories.map((category, idx) => (
              <div 
                key={category.id} 
                onClick={() => setViewState({ view: 'dish-viewer', currentCategory: category.id, currentDishIndex: 0 })}
                className="group cursor-pointer relative h-[600px] rounded-3xl overflow-hidden hover-lift animate-slide-up bg-[#1A1A1A] border border-white/5"
                style={{ animationDelay: `${idx * 150}ms` }}
              >
                {/* Background Image */}
                <div className="absolute inset-0">
                  <ImageWithFallback 
                    src={category.image} 
                    alt={category.name} 
                    className="group-hover:scale-110 transition-transform duration-[1.5s]" 
                  />
                  {/* Overlay */}
                  <div className="absolute inset-0 card-overlay group-hover:bg-black/20 transition-all duration-500"></div>
                </div>

                {/* Card Content */}
                <div className="absolute inset-0 p-10 flex flex-col justify-end items-start">
                  <div className="mb-4">
                    <span className="text-[10px] font-bold uppercase tracking-[0.3em] text-gold mb-2 block animate-slide-up">
                      COASTAL HERITAGE
                    </span>
                    <h2 className="text-4xl font-light tracking-tight text-white mb-2 leading-tight">
                      {category.name}
                    </h2>
                  </div>

                  <div className="w-full pt-10 mt-2 opacity-0 group-hover:opacity-100 translate-y-4 group-hover:translate-y-0 transition-all duration-500">
                    <button className="border border-white/30 hover:border-white hover:bg-white hover:text-black transition-all px-8 py-3 text-[10px] font-bold uppercase tracking-widest bg-black/40 backdrop-blur-sm">
                      Discover Menu
                    </button>
                  </div>

                  {/* Initial view button style as per design reference */}
                  <div className="w-full mt-2 group-hover:hidden transition-opacity">
                    <button className="border border-white/20 px-8 py-3 text-[10px] font-bold uppercase tracking-widest text-white/70">
                      Discover Menu
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Global Settings Trigger - Visible in overview */}
