                onClick={onOpenSettings}
                className="p-5 bg-white text-black rounded-full shadow-2xl hover:scale-110 transition-all border border-white/10"
            >
                <Settings size={24} />
            </button>
        </div>
      </div>
    );
  }

  if (!currentDish) return <div className="h-screen w-full bg-[#0F0F0F] flex items-center justify-center"><Loader2 className="animate-spin text-gold" size={48} /></div>;

  return (
    <div className="min-h-screen flex flex-col bg-[#0F0F0F] text-white">
      <header className="px-8 py-6 flex justify-between items-center border-b border-white/5 bg-black/40 backdrop-blur-xl sticky top-0 z-50">
        <button onClick={() => setViewState((p: any) => ({...p, view: 'menu-overview'}))} className="p-3 hover:bg-white/10 rounded-full transition-all text-gray-400 hover:text-white">
          <Home size={22} />
        </button>
        <div className="text-center">
          <h2 className={`text-sm font-light tracking-[0.3em] uppercase ${isClassic ? 'italic font-serif' : ''}`}>{appTitle}</h2>
          <div className="text-[10px] text-gold font-bold uppercase tracking-widest mt-1">{viewState.currentDishIndex + 1} / {currentCategoryDishes.length}</div>
        </div>
        <button onClick={onOpenSettings} className="p-3 hover:bg-white/10 rounded-full transition-all text-gray-400 hover:text-white">
          <Settings size={22} />
