          <div className="absolute -inset-10 bg-gold/10 rounded-full blur-3xl opacity-30 -z-10 group-hover:opacity-50 transition-opacity"></div>
          <div className="w-full aspect-square rounded-[2rem] overflow-hidden shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8)] border border-white/10">
