          <div className="absolute -bottom-6 -right-6 p-8 bg-[#1A1A1A] border border-white/10 rounded-3xl shadow-2xl flex items-center gap-6">
             <div className="p-3 bg-gold/10 rounded-2xl">
                <Flame className="text-gold animate-pulse" size={28} />
             </div>
             <div>
                <div className="text-3xl font-light">{currentDish.nutrition.calories}</div>
