            <h1 className={`text-5xl md:text-7xl font-thin leading-tight tracking-tight ${isClassic ? 'italic font-serif' : ''}`}>
              {currentDish.name}
            </h1>
            <p className="text-xl text-gray-400 font-light italic leading-relaxed max-w-xl">
              {currentDish.description}
            </p>
          </div>

          <div className="flex flex-wrap gap-4">
             {currentDish.suitableFor.map(tag => {
               const config = TAG_CONFIG[tag];
               const Icon = config.icon;
               return (
                 <span key={tag} className="px-5 py-2.5 rounded-full border border-white/10 bg-white/5 text-[10px] font-bold uppercase tracking-widest flex items-center gap-3 text-gray-300">
