          <div className="grid grid-cols-4 gap-8 py-10 border-y border-white/5">
             {[
               { label: 'Protein', value: currentDish.nutrition.protein },
               { label: 'Fat', value: currentDish.nutrition.fat },
               { label: 'Carbs', value: currentDish.nutrition.carbohydrates },
