             ].map(stat => (
               <div key={stat.label}>
                 <div className="text-3xl font-light text-white mb-1">{stat.value}<span className="text-sm ml-0.5 text-gray-500">g</span></div>
                 <div className="text-[10px] font-bold uppercase tracking-widest text-gray-600">{stat.label}</div>
