import React from 'react';
import { ThemeType } from '../types';

interface ThemeWrapperProps {
  theme: ThemeType;
  children: React.ReactNode;
  className?: string;
}

export const ThemeWrapper: React.FC<ThemeWrapperProps> = ({ theme, children, className = '' }) => {
  let themeClasses = 'theme-transition ';

  switch (theme) {
    case 'modern':
      // Updated to use a darker base to support the new premium redesign
      themeClasses += 'bg-[#0F0F0F] font-["Inter"] text-white';
      break;
    case 'classic':
      // Keep parchment for classic but maybe darken the background slightly if we want it to feel premium
      themeClasses += 'bg-[#FDFBF7] font-["Playfair_Display"] text-[#2C2C2C]';
      break;
    default:
      themeClasses += 'bg-[#0F0F0F] font-sans text-white';
  }

  return (
    <div className={`min-h-screen w-full ${themeClasses} ${className}`}>
      {children}
    </div>
  );
};

export const getThemeButtonClass = (theme: ThemeType) => {
    switch (theme) {
        case 'modern': return 'bg-white text-black hover:bg-gray-200 rounded-xl px-6 py-2 transition-all';
        case 'classic': return 'bg-[#2C2C2C] text-white hover:bg-black border border-[#2C2C2C] px-6 py-2 italic transition-all';
        default: return 'bg-blue-600 text-white hover:bg-blue-700 rounded-lg';
    }
}

