          <Maximize2 size={24} />
        </div>
      </div>

      {/* Dietary Tags - Premium glassmorphic style */}
      <div className="absolute bottom-8 left-8 flex flex-wrap gap-2 pr-8 pointer-events-none">
        {dish.suitableFor && dish.suitableFor.length > 0 ? (
          dish.suitableFor.map((tag) => (
            <span key={tag} className="bg-white/70 backdrop-blur-2xl text-black text-[9px] font-black uppercase tracking-widest px-4 py-2 rounded-full shadow-lg border border-white/40 whitespace-nowrap">
              {tag.replace('-', ' ')}
