        ) : (
          <span className="bg-[#FFD700]/80 backdrop-blur-2xl text-black text-[9px] font-black uppercase tracking-widest px-4 py-2 rounded-full shadow-lg border border-white/40">
            Signature Creation
          </span>
        )}
