            label="Fat" 
            value={dish.nutrition.fat} 
            icon={Droplets}
          />
          <NutritionStat 
            label="Carb" 
            value={dish.nutrition.carbohydrates} 
            icon={Wheat}
          />
          <NutritionStat 
            label="Fiber" 
            value={dish.nutrition.fiber} 
            isLast 
            icon={Feather}
            colorClass="text-black" 
          />
        </div>
      </div>
    </div>
  </div>
);

