    onClick={onClose}
  >
    <button 
      className="absolute top-10 right-10 text-white/40 hover:text-white p-4 transition-all hover:rotate-90 duration-500"
      onClick={(e) => { e.stopPropagation(); onClose(); }}
    >
      <X size={40} />
    </button>
    <img 
      src={src} 
      className="max-w-full max-h-full object-contain rounded-3xl shadow-[0_40px_100px_-20px_rgba(0,0,0,0.8)] border border-white/10 animate-scale-in select-none" 
      alt="Full size"
      onClick={(e) => e.stopPropagation()}
    />
  </div>
);

