    return () => window.removeEventListener('keydown', handleEsc);
  }, []);

  if (viewState.view === 'menu-overview') {
    return (
      <div className="min-h-screen bg-[#FBFBFA] text-slate-900 selection:bg-slate-900 selection:text-white">
