      {zoomedImage && <Lightbox src={zoomedImage} onClose={() => setZoomedImage(null)} />}

      <header className="px-12 py-10 flex justify-between items-center bg-white/80 backdrop-blur-2xl border-b border-gray-100 sticky top-0 z-50">
        <button 
