export const ClientView: React.FC<ClientViewProps> = ({ categories, dishes, viewState, setViewState, theme, appTitle, appSubtitle, onOpenSettings }) => {
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);
  const isClassic = theme === 'classic';

  // Handle escape key to close lightbox
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setZoomedImage(null);
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, []);

  if (viewState.view === 'menu-overview') {
    return (
      <div className="min-h-screen bg-[#FBFBFA] text-slate-900 selection:bg-slate-900 selection:text-white">
