          <header className="mb-20 max-w-4xl animate-slide-up">
            <div className="relative mb-8">
              <h1 className="text-5xl md:text-7xl font-extralight tracking-tight text-slate-400 mb-1 leading-none">
                {appTitle}
              </h1>
              <div className="text-6xl md:text-8xl text-[#D1C2A4] italic font-['Playfair_Display'] font-normal leading-none -mt-4 md:-mt-6 ml-1 drop-shadow-sm">
