              </div>
            </div>
            <div className="w-24 h-[1px] bg-slate-200 mb-8"></div>
            <p className="text-slate-400 text-lg md:text-xl font-light leading-relaxed max-w-xl tracking-tight">
              {appSubtitle || "A curated anthology of culinary experiences, bridging the gap between historical heritage and modern avant-garde."}
            </p>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12 md:gap-16">
            {categories.map((category, idx) => {
              const categoryDishCount = dishes.filter(d => d.categoryId === category.id).length;

              return (
                <div 
                  key={category.id} 
                  onClick={() => setViewState({ view: 'dish-viewer', currentCategory: category.id, currentDishIndex: 0 })}
                  className="group cursor-pointer relative h-[650px] rounded-[3.5rem] overflow-hidden bg-white border border-slate-100 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.06)] transition-all duration-700 hover:translate-y-[-12px] hover:shadow-[0_50px_100px_-20px_rgba(0,0,0,0.1)]"
                  style={{ animationDelay: `${idx * 120}ms` }}
                >
                  <div className="absolute inset-0">
                    <ImageWithFallback src={category.image} alt={category.name} className="group-hover:scale-110 transition-transform duration-[3s] ease-out" />

                    {/* Legibility Layer - Reduced height for clear top as per request */}
                    <div className="absolute inset-x-0 bottom-0 h-2/3 bg-gradient-to-t from-white via-white/40 to-transparent opacity-100 transition-opacity duration-700"></div>
                  </div>

                  {/* Glassmorphic Content Plate - Added gradient mask to fade the glass effect at the top */}
                  <div 
                    className="absolute inset-x-0 bottom-0 p-14 pt-24 flex flex-col justify-end items-start bg-gradient-to-t from-white/95 via-white/50 to-transparent backdrop-blur-2xl"
                    style={{ 
                      maskImage: 'linear-gradient(to top, black 70%, transparent)', 
                      WebkitMaskImage: 'linear-gradient(to top, black 70%, transparent)' 
                    }}
                  >
                    <span className="text-[10px] font-black uppercase tracking-[0.6em] text-[#B08D57] mb-4 opacity-100 group-hover:scale-110 transition-all duration-700">
                      {categoryDishCount} {categoryDishCount === 1 ? 'Featured Creation' : 'Featured Creations'}
                    </span>
                    <h2 className="text-5xl font-bold tracking-tight text-slate-900 mb-8 group-hover:text-[#B08D57] transition-colors duration-500 drop-shadow-sm">
                      {category.name}
                    </h2>
                    <div className="w-12 h-1 bg-slate-900/10 mb-10 group-hover:w-full transition-all duration-700 rounded-full"></div>
                    <button className="px-12 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-white bg-slate-900 shadow-2xl group-hover:bg-[#B08D57] group-hover:scale-105 transition-all duration-500 rounded-full">
                      View Menu
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  const currentCategoryDishes = dishes.filter(d => d.categoryId === viewState.currentCategory);
  const activeCategory = categories.find(c => c.id === viewState.currentCategory);

  return (
    <div className="min-h-screen bg-[#FBFBFB] text-black font-['Inter'] selection:bg-black selection:text-white">
      {zoomedImage && <Lightbox src={zoomedImage} onClose={() => setZoomedImage(null)} />}

      <header className="px-12 py-10 flex justify-between items-center bg-white/80 backdrop-blur-2xl border-b border-gray-100 sticky top-0 z-50">
        <button 
          onClick={() => setViewState((p: any) => ({...p, view: 'menu-overview'}))} 
          className="flex items-center gap-5 group"
        >
          <div className="p-4 bg-gray-50 rounded-full group-hover:bg-black group-hover:text-white transition-all duration-500 shadow-sm">
            <Home size={22} />
          </div>
          <div className="hidden md:block text-left">
            <span className="text-[10px] font-black uppercase tracking-widest block text-gray-400 mb-0.5">Return to</span>
            <span className="text-sm font-bold tracking-tight">Main Selection</span>
          </div>
        </button>

        <div className="text-center">
          <h2 className={`text-2xl font-black tracking-tighter uppercase mb-1 ${isClassic ? 'font-serif italic' : ''}`}>
            {activeCategory?.name || appTitle}
