          <div className="flex items-center justify-center gap-2">
            <div className="w-8 h-px bg-gray-200"></div>
            <span className="text-[10px] text-gray-400 font-bold uppercase tracking-[0.3em]">
              {currentCategoryDishes.length} Featured Creations
            </span>
            <div className="w-8 h-px bg-gray-200"></div>
          </div>
        </div>

        <button 
          onClick={onOpenSettings} 
          className="p-4 bg-gray-50 hover:bg-black hover:text-white rounded-full transition-all duration-500 shadow-sm"
        >
          <Settings size={22} />
        </button>
      </header>

      <main className="max-w-[1800px] mx-auto px-8 md:px-16 py-24">
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-16 md:gap-20">
          {currentCategoryDishes.map((dish, idx) => (
            <DishCard 
              key={dish.id} 
              dish={dish} 
              isClassic={isClassic} 
              onImageClick={setZoomedImage}
              index={idx}
            />
          ))}
        </div>

        {currentCategoryDishes.length === 0 && (
          <div className="h-[60vh] flex flex-col items-center justify-center text-center animate-fade-in">
             <div className="p-10 bg-white shadow-xl rounded-[3rem] mb-10 border border-gray-100">
                <Feather size={56} className="text-gray-200" />
             </div>
             <h3 className="text-3xl font-black mb-4 tracking-tight">Curation in Progress</h3>
             <p className="text-gray-400 max-w-sm text-lg font-light leading-relaxed">Our culinary team is currently perfecting this collection. Return shortly for a sensory update.</p>
          </div>
        )}
      </main>
    </div>
  );
};

