        )}
      </div>
    </div>

    <div className="p-10 flex-1 flex flex-col">
      <div className="mb-10">
        <h3 className={`text-4xl font-black tracking-tight text-[#1A1A1A] mb-8 leading-[1.05] ${isClassic ? 'font-serif italic' : ''}`}>
