        <div className="absolute top-8 left-8 z-20 w-12 h-12 flex items-center justify-center bg-gray-400/20 backdrop-blur-md text-gray-600 text-xs font-black rounded-full border border-white/20 shadow-sm select-none">
          {(index + 1).toString().padStart(2, '0')}
        </div>

        <ImageWithFallback src={dish.image} alt={dish.name} className="group-hover:scale-110 transition-transform duration-[3s] ease-out" />

        {/* Zoom Indicator */}
        <div className="absolute inset-0 bg-black/10 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center">
          <div className="p-4 bg-white/30 rounded-full text-white scale-75 group-hover/img:scale-100 transition-transform duration-500 border border-white/20">
            <Maximize2 size={24} />
          </div>
        </div>
      </div>

      <div className="pt-10 px-2 flex-1 flex flex-col">
        <div className="mb-6">
          <h3 className={`text-5xl font-black tracking-tight text-[#222222] mb-6 leading-none ${isClassic ? 'font-serif italic' : ''}`}>
            {dish.name}
          </h3>

          <div className="flex flex-wrap items-center gap-x-2 gap-y-1 mb-8 opacity-40">
            {allComponents.map((item, idx) => (
              <React.Fragment key={idx}>
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-800 whitespace-nowrap">
                  {item}
                </span>
                {idx < allComponents.length - 1 && (
                  <span className="text-[10px] text-gray-400">•</span>
                )}
              </React.Fragment>
            ))}
          </div>

          <p className="text-gray-400 text-lg font-light leading-relaxed line-clamp-3 italic max-w-lg">
            {dish.description}
