                    </div>

                    {activeTab === 'categories' ? (
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                            <button 
                                onClick={() => setEditingCategory({})}
                                className="h-64 border-2 border-dashed border-gray-300 rounded-2xl flex flex-col items-center justify-center text-gray-400 hover:border-black hover:text-black hover:bg-gray-50 transition-all group"
                            >
                                <div className="p-4 bg-gray-100 rounded-full mb-4 group-hover:scale-110 transition-transform"><Plus size={32} /></div>
                                <span className="font-medium">New Category</span>
                            </button>
                            {categories.map((cat, i) => (
                                <div key={cat.id} className={`bg-white rounded-2xl shadow-sm hover:shadow-xl transition-all duration-300 overflow-hidden group relative animate-slide-up ${cat.isHidden ? 'opacity-75' : ''}`} style={{animationDelay: `${i*100}ms`}}>
                                    <div className="h-40 overflow-hidden relative">
                                        <img src={cat.image} className={`w-full h-full object-cover transform group-hover:scale-110 transition-transform duration-700 ${cat.isHidden ? 'grayscale' : ''}`} />
