                                            <div className="absolute inset-0 flex items-center justify-center bg-black/10 backdrop-blur-[1px]">
                                                 <span className="bg-black/70 text-white text-xs px-2 py-1 rounded uppercase font-bold tracking-wider">Hidden</span>
                                            </div>
                                        )}
                                    </div>
                                    <div className="p-6">
                                        <h4 className="font-bold text-xl mb-2 flex items-center gap-2">
                                            {cat.name}
                                            {cat.isHidden && <EyeOff size={14} className="text-gray-400"/>}
                                        </h4>
                                        <p className="text-sm text-gray-500 line-clamp-2 leading-relaxed">{cat.description}</p>
                                    </div>
                                    <div className="absolute top-3 right-3 flex gap-2 opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0 z-10">
                                         <button onClick={() => toggleCategoryVisibility(cat)} className="p-2 bg-white/90 backdrop-blur rounded-full shadow hover:bg-black hover:text-white transition-colors" title={cat.isHidden ? "Show" : "Hide"}>
