                                        </button>
                                        <button onClick={() => duplicateCategory(cat)} className="p-2 bg-white/90 backdrop-blur rounded-full shadow hover:bg-black hover:text-white transition-colors" title="Duplicate">
                                            <Copy size={16}/>
                                        </button>
                                        <button onClick={() => setEditingCategory(cat)} className="p-2 bg-white/90 backdrop-blur rounded-full shadow hover:bg-black hover:text-white transition-colors"><Edit size={16}/></button>
