                                    <div className="px-3 py-2 border-r border-gray-100 text-gray-400">
                                        <ArrowUpDown size={16} />
                                    </div>
                                    <select 
                                        value={sortBy}
                                        onChange={(e) => setSortBy(e.target.value as any)}
                                        className="bg-transparent py-2 pl-3 pr-8 text-sm font-medium text-gray-700 outline-none cursor-pointer hover:bg-gray-50 rounded-r-xl appearance-none"
                                        style={{backgroundImage: 'none'}}
                                    >
                                        <option value="default">Default Order</option>
                                        <option value="calories-high">Calories (High → Low)</option>
                                        <option value="calories-low">Calories (Low → High)</option>
                                        <option value="name-asc">Alphabetical (A-Z)</option>
                                    </select>
                                </div>

                                <button onClick={() => { setEditingDish({ nutrition: { calories: 0, protein: 0, fat: 0, carbohydrates: 0, fiber: 0 } }); setSuggestedDesc(null); setLastImage(null); }} className="flex items-center gap-2 bg-black text-white px-6 py-3 rounded-xl shadow-lg hover:shadow-xl hover:-translate-y-1 transition-all">
                                    <Plus size={18}/> Add New Dish
                                </button>
                            </div>
                            {categories.map(cat => {
                                const catDishes = dishes.filter(d => d.categoryId === cat.id);
                                const sortedDishes = [...catDishes].sort((a, b) => {
                                    if (sortBy === 'calories-high') return b.nutrition.calories - a.nutrition.calories;
                                    if (sortBy === 'calories-low') return a.nutrition.calories - b.nutrition.calories;
                                    if (sortBy === 'name-asc') return a.name.localeCompare(b.name);
                                    return 0;
                                });

                                return (
                                    <div 
                                        key={cat.id} 
                                        className={`bg-white/50 backdrop-blur-sm p-6 rounded-3xl border transition-all duration-300 ${dragOverCategoryId === cat.id ? 'border-blue-400 bg-blue-50/50 scale-[1.01] shadow-lg' : 'border-white/50'}`}
                                        onDragOver={(e) => handleDragOver(e, cat.id)}
                                        onDrop={(e) => handleDrop(e, cat.id)}
                                    >
                                        <h3 className="text-xl font-bold mb-6 ml-2 flex items-center gap-2">
                                            <span className={`w-2 h-8 rounded-full transition-colors ${dragOverCategoryId === cat.id ? 'bg-blue-500' : 'bg-black'}`}></span>
                                            {cat.name}
                                        </h3>
                                        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 min-h-[100px]">
                                            {sortedDishes.length === 0 && (
                                                <div className="col-span-full border-2 border-dashed border-gray-200 rounded-2xl flex items-center justify-center text-gray-400 text-sm font-medium h-32">
                                                    Drag dishes here
                                                </div>
                                            )}
                                            {sortedDishes.map((dish, index) => {
                                                const displayNum = (index + 1).toString().padStart(2, '0');
                                                return (
                                                    <div 
                                                        key={dish.id} 
                                                        className={`bg-white rounded-2xl p-3 gap-3 shadow-sm hover:shadow-md transition-all group relative border border-transparent hover:border-gray-100 ${dish.isHidden ? 'opacity-60 bg-gray-50' : ''} ${sortBy === 'default' ? 'cursor-move' : ''}`}
                                                        draggable={sortBy === 'default'}
                                                        onDragStart={(e) => handleDragStart(e, dish.id)}
                                                        onDragEnd={handleDragEnd}
                                                        onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); }}
                                                        onDrop={(e) => handleDishReorder(e, dish)}
                                                    >
                                                        {sortBy === 'default' && (
                                                            <div className="absolute top-0 left-0 right-0 h-6 flex justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10 pointer-events-none">
                                                                <GripVertical size={16} className="text-gray-300 mt-1" />
                                                            </div>
                                                        )}
                                                        <div className="flex items-center gap-4 mt-2">
                                                            <div className="relative">
                                                                <img src={dish.image} className={`w-20 h-20 rounded-xl object-cover shadow-sm group-hover:scale-105 transition-transform ${dish.isHidden ? 'grayscale' : ''}`} />
                                                                {displayNum && (
                                                                    <div className="absolute top-1 left-1 bg-black/50 backdrop-blur-md text-white text-[10px] font-mono font-bold px-1.5 py-0.5 rounded border border-white/20">
                                                                        {displayNum}
                                                                    </div>
                                                                )}
                                                            </div>
                                                            <div className="flex-1 min-w-0">
                                                                <div className="font-bold truncate text-gray-800">{dish.name}</div>
                                                                <div className="text-xs text-orange-500 font-mono font-medium mt-1 bg-orange-50 inline-block px-2 py-1 rounded">{dish.nutrition.calories} kcal</div>
                                                            </div>
                                                        </div>
                                                        <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity flex gap-1 bg-white/90 backdrop-blur-sm p-1 rounded-full shadow-sm z-20">
                                                            <button onClick={() => toggleVisibility(dish)} className="p-1.5 hover:bg-gray-100 rounded-full transition-colors text-gray-600" title={dish.isHidden ? "Show Dish" : "Hide Dish"}>
                                                                {dish.isHidden ? <EyeOff size={14} /> : <Eye size={14} />}
                                                            </button>
                                                            <button onClick={() => duplicateDish(dish)} className="p-1.5 hover:bg-gray-100 rounded-full transition-colors text-blue-600" title="Duplicate">
                                                                <Copy size={14} />
                                                            </button>
                                                            <button onClick={() => { setEditingDish(dish); setSuggestedDesc(null); setLastImage(null); }} className="p-1.5 hover:bg-gray-100 rounded-full transition-colors text-gray-600" title="Edit">
                                                                <Edit size={14} />
                                                            </button>
                                                            <button onClick={() => removeDish(dish.id)} className="p-1.5 hover:bg-red-50 rounded-full transition-colors text-red-500" title="Delete">
                                                                <Trash2 size={14} />
                                                            </button>
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </>
            )}
        </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { CuisineCategory, Dish, ThemeType, SuitableForTag } from '../types';
import { 
  ChevronLeft, Home, Settings, Flame, Beef, Coffee, 
  Sun, Moon, Zap, Activity, Feather, Wheat, Loader2, ArrowRight,
  Droplets, X, Maximize2
} from 'lucide-react';

interface ClientViewProps {
  categories: CuisineCategory[];
  dishes: Dish[];
  viewState: {
    view: 'menu-overview' | 'dish-viewer';
    currentCategory: string | null;
    currentDishIndex: number;
  };
  setViewState: React.Dispatch<React.SetStateAction<any>>;
  theme: ThemeType;
  appTitle: string;
  appSubtitle: string;
  isOffline?: boolean;
  onOpenSettings?: () => void;
}

const ImageWithFallback = ({ src, alt, className }: { src: string; alt: string; className: string }) => {
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(true);

  return (
    <div className={`relative w-full h-full bg-[#F3F4F6] overflow-hidden ${className}`}>
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center bg-[#F3F4F6] z-10">
          <Loader2 className="animate-spin text-gray-300" size={32} />
        </div>
      )}
      <img
        src={error ? 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&q=80&w=800' : src}
        alt={alt}
        className={`w-full h-full object-cover transition-all duration-1000 ${loading ? 'opacity-0 scale-110' : 'opacity-100 scale-100'}`}
        onLoad={() => setLoading(false)}
        onError={() => {
          setError(true);
          setLoading(false);
        }}
      />
    </div>
  );
};

const NutritionStat = ({ 
  label, 
  value, 
  unit = 'g', 
  isLast = false, 
  colorClass = "text-black",
  icon: Icon,
  animate = false
}: { 
  label: string, 
  value: number | string, 
  unit?: string, 
  isLast?: boolean, 
  colorClass?: string,
  icon?: React.ElementType,
  animate?: boolean
}) => (
  <div className={`flex-1 flex flex-col items-center px-1 ${!isLast ? 'border-r border-gray-100' : ''}`}>
    <div className="flex items-center gap-1.5 mb-2 group">
      {Icon && <Icon size={12} className={`${animate ? 'text-orange-500' : 'text-gray-200'} group-hover:text-gray-400 transition-colors`} />}
      <div className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-300">{label}</div>
    </div>
    <div className={`text-2xl font-black leading-none tracking-tighter ${colorClass} ${animate ? 'animate-pulse' : ''}`}>
      {value}<span className="text-[10px] ml-0.5 opacity-40 font-bold lowercase tracking-normal">{unit}</span>
    </div>
  </div>
);

const DishCard = ({ dish, isClassic, onImageClick, index }: { dish: Dish, isClassic: boolean, onImageClick: (src: string) => void, index: number }) => {
  const allComponents = [...dish.sideDishes, ...dish.ingredients];

  return (
    <div className="bg-transparent overflow-hidden flex flex-col group transition-all duration-500 h-full opacity-0 animate-slide-up" style={{ animationFillMode: 'forwards' }}>
      <div 
        className="relative aspect-[16/10] overflow-hidden cursor-zoom-in group/img rounded-[3rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] border border-gray-50 bg-white"
        onClick={() => onImageClick(dish.image)}
      >
        <div className="absolute top-8 left-8 z-20 w-12 h-12 flex items-center justify-center bg-gray-400/20 backdrop-blur-md text-gray-600 text-xs font-black rounded-full border border-white/20 shadow-sm select-none">
          {(index + 1).toString().padStart(2, '0')}
        </div>

        <ImageWithFallback src={dish.image} alt={dish.name} className="group-hover:scale-110 transition-transform duration-[3s] ease-out" />

        <div className="absolute inset-0 bg-black/10 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center">
          <div className="p-4 bg-white/30 rounded-full text-white scale-75 group-hover/img:scale-100 transition-transform duration-500 border border-white/20">
            <Maximize2 size={24} />
          </div>
        </div>
      </div>

      <div className="pt-10 px-2 flex-1 flex flex-col">
        <div className="mb-6">
          <h3 className={`text-5xl font-black tracking-tight text-[#222222] mb-6 leading-none ${isClassic ? 'font-serif italic' : ''}`}>
            {dish.name}
          </h3>

          <div className="flex flex-wrap items-center gap-x-2 gap-y-1 mb-8 opacity-40">
            {allComponents.map((item, idx) => (
              <React.Fragment key={idx}>
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-800 whitespace-nowrap">
                  {item}
                </span>
                {idx < allComponents.length - 1 && (
                  <span className="text-[10px] text-gray-400">•</span>
                )}
              </React.Fragment>
            ))}
          </div>

          <p className="text-gray-400 text-lg font-light leading-relaxed line-clamp-3 italic max-w-lg">
            {dish.description}
          </p>
        </div>

        <div className="mt-auto pt-8 flex items-center justify-between border-t border-gray-100 opacity-80">
          <NutritionStat label="Cals" value={dish.nutrition.calories} unit="" icon={Flame} colorClass="text-orange-500" animate={true} />
          <NutritionStat label="Prot" value={dish.nutrition.protein} icon={Beef} />
          <NutritionStat label="Fat" value={dish.nutrition.fat} icon={Droplets} />
          <NutritionStat label="Carb" value={dish.nutrition.carbohydrates} icon={Wheat} />
          <NutritionStat label="Fiber" value={dish.nutrition.fiber} isLast icon={Feather} colorClass="text-black" />
        </div>
      </div>
    </div>
  );
};

const Lightbox = ({ src, onClose }: { src: string; onClose: () => void }) => (
  <div 
    className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 cursor-zoom-out animate-fade-in p-6 md:p-20"
    onClick={onClose}
  >
    <button 
      className="absolute top-10 right-10 text-white/40 hover:text-white p-4 transition-all hover:rotate-90 duration-500"
      onClick={(e) => { e.stopPropagation(); onClose(); }}
    >
      <X size={40} />
    </button>
    <img 
      src={src} 
      className="max-w-full max-h-full object-contain rounded-3xl shadow-2xl border border-white/10 animate-scale-in select-none" 
      alt="Full size"
      onClick={(e) => e.stopPropagation()}
    />
  </div>
);

