import React, { useState, useEffect } from 'react';
import { AppState, CuisineCategory, Dish, ThemeType } from './types';
import { ThemeWrapper, getThemeButtonClass } from './components/ThemeWrapper';
import { AdminPanel } from './components/AdminPanel';
import { ClientView, PDFExportView } from './components/ClientView';
import { AuthForm } from './components/AuthForm';
import { Settings, ChefHat, Palette, FileText, X, Menu, Loader2, Database, Copy, Check, ArrowRight } from 'lucide-react';
import { fetchCategories, fetchDishes, supabase } from './services/supabaseService';
import { User } from '@supabase/supabase-js';

const SQL_SCHEMA = `-- 1. Categories Table (Updated with BG Support)
CREATE TABLE IF NOT EXISTS categories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  description TEXT,
  image TEXT,
  bg_color TEXT,
  bg_image TEXT,
  is_hidden BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 2. Dishes Table
CREATE TABLE IF NOT EXISTS dishes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  category_id UUID REFERENCES categories(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT,
  image TEXT,
  side_dishes JSONB DEFAULT '[]'::jsonb,
  ingredients JSONB DEFAULT '[]'::jsonb,
  nutrition JSONB DEFAULT '{}'::jsonb,
  suitable_for JSONB DEFAULT '[]'::jsonb,
  is_hidden BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 3. Enable RLS
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE dishes ENABLE ROW LEVEL SECURITY;

-- 4. Create Public Access Policies
DROP POLICY IF EXISTS "Public Access" ON categories;
CREATE POLICY "Public Access" ON categories FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public Access" ON dishes;
CREATE POLICY "Public Access" ON dishes FOR ALL USING (true) WITH CHECK (true);`;

const App: React.FC = () => {
  const [categories, setCategories] = useState<CuisineCategory[]>([]);
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [user, setUser] = useState<User | null>(null);
  const [showAuth, setShowAuth] = useState(false);

  const [viewState, setViewState] = useState<AppState['view']>('menu-overview');
  const [currentCategory, setCurrentCategory] = useState<string | null>(null);
  const [currentDishIndex, setCurrentDishIndex] = useState(0);
  const [theme, setTheme] = useState<ThemeType>('modern');

  const [appTitle, setAppTitle] = useState("Artisan Kitchen");
  const [appSubtitle, setAppSubtitle] = useState("Private Dining Curations");
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Auth State Listener
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
    });

    return () => subscription.unsubscribe();
  }, []);

  // Initial Data Fetch
  useEffect(() => {
    const loadData = async () => {
      try {
        const [cats, ds] = await Promise.all([fetchCategories(), fetchDishes()]);
        setCategories(cats);
        setDishes(ds);
        setDbError(null);
      } catch (err: any) {
        console.error("Supabase load error:", err);
        if (err.code === 'PGRST205' || err.message?.includes('not found')) {
          setDbError('DATABASE_SETUP_REQUIRED');
        } else {
          setDbError(err.message || 'Unknown database error');
        }
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  const handleCopySQL = () => {
    navigator.clipboard.writeText(SQL_SCHEMA);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleAdminAccess = () => {
    if (user) {
      setViewState('admin');
      setIsSettingsOpen(false);
    } else {
      setShowAuth(true);
    }
  };

  if (loading) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-white gap-4">
        <Loader2 className="animate-spin text-gray-300" size={48} />
        <span className="text-xs uppercase tracking-widest text-gray-400 font-bold">Synchronizing with Kitchen...</span>
      </div>
    );
  }

  if (dbError === 'DATABASE_SETUP_REQUIRED') {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-gray-50 p-6 overflow-auto">
        <div className="max-w-3xl w-full bg-white rounded-3xl shadow-2xl p-10 border border-gray-100">
          <div className="flex items-center gap-4 mb-6">
            <div className="p-3 bg-amber-100 text-amber-600 rounded-2xl">
              <Database size={32} />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Database Setup Required</h1>
              <p className="text-gray-500">Your Supabase tables are missing. Please run the SQL below in your dashboard.</p>
            </div>
          </div>

          <div className="relative group">
            <pre className="bg-gray-900 text-gray-300 p-6 rounded-2xl text-xs overflow-x-auto font-mono leading-relaxed max-h-[400px]">
              {SQL_SCHEMA}
            </pre>
            <button 
              onClick={handleCopySQL}
              className="absolute top-4 right-4 bg-white/10 hover:bg-white/20 text-white p-2 rounded-xl backdrop-blur-md transition-all flex items-center gap-2 text-xs font-bold uppercase tracking-wider"
            >
              {copied ? <Check size={16} className="text-green-400" /> : <Copy size={16} />}
              {copied ? 'Copied!' : 'Copy SQL'}
            </button>
          </div>

          <div className="mt-8 flex flex-col gap-4">
             <p className="text-sm text-gray-600">
               1. Go to your <a href="https://supabase.com/dashboard" target="_blank" className="text-blue-600 font-bold hover:underline">Supabase Dashboard</a>.<br/>
               2. Navigate to <b>SQL Editor</b> > <b>New Query</b>.<br/>
               3. Paste the code above and click <b>Run</b>.
             </p>
             <button 
                onClick={() => window.location.reload()}
                className="w-full bg-black text-white py-4 rounded-2xl font-bold shadow-lg hover:bg-gray-800 transition-all flex items-center justify-center gap-2"
              >
                <Loader2 size={18} />
                I've run the SQL, Reload App
             </button>
          </div>
        </div>
      </div>
    );
  }

  const visibleCategories = categories.filter(c => !c.isHidden);
  const visibleDishes = dishes.filter(d => 
    !d.isHidden && visibleCategories.some(c => c.id === d.categoryId)
  );

  const safeCurrentDishIndex = (currentDishIndex >= visibleDishes.length) ? 0 : currentDishIndex;

  const clientViewState = {
      view: viewState === 'menu-overview' || viewState === 'dish-viewer' ? viewState : 'menu-overview',
      currentCategory,
      currentDishIndex: safeCurrentDishIndex
  };

  const setClientViewState = (newState: any) => {
     if (typeof newState === 'function') {
         const res = newState(clientViewState);
         setViewState(res.view);
         setCurrentCategory(res.currentCategory);
         setCurrentDishIndex(res.currentDishIndex);
     } else {
         setViewState(newState.view);
         setCurrentCategory(newState.currentCategory);
         setCurrentDishIndex(newState.currentDishIndex);
     }
  };

  return (
    <ThemeWrapper theme={theme}>
        {showAuth && (
          <AuthForm 
            onSuccess={() => { setShowAuth(false); setViewState('admin'); setIsSettingsOpen(false); }}
            onCancel={() => setShowAuth(false)}
          />
        )}

        {/* Settings Panel Trigger - Now enabled in dish-viewer too */}
        {(viewState === 'menu-overview' || viewState === 'dish-viewer') && (
            <div className="fixed top-6 right-6 z-[60] print:hidden">
                <button
                    onClick={() => setIsSettingsOpen(!isSettingsOpen)}
                    className={`p-4 rounded-full shadow-2xl hover:scale-110 transition-all flex items-center justify-center ${isSettingsOpen ? 'bg-black text-white' : 'bg-white text-black'}`}
                >
                    {isSettingsOpen ? <X size={24} /> : <Settings size={24} />}
                </button>
            </div>
        )}

        {/* Branding & AI Panel */}
        {isSettingsOpen && (
            <div className="fixed top-24 right-6 z-[70] w-96 bg-white/95 backdrop-blur-2xl p-8 rounded-[2rem] shadow-[0_20px_60px_-10px_rgba(0,0,0,0.3)] border border-white/50 animate-scale-in origin-top-right print:hidden max-h-[85vh] overflow-y-auto no-scrollbar">
                <div className="space-y-8">
                    <div>
                        <div className="flex items-center gap-3 mb-6">
                            <Palette size={20} className="text-gray-800"/>
                            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-gray-800">Visual Identity</h3>
                        </div>

                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Restaurant Name</label>
                                <input 
                                    type="text" 
                                    value={appTitle} 
                                    onChange={e => setAppTitle(e.target.value)}
                                    className="w-full bg-gray-50 border-none p-4 rounded-xl text-sm font-bold focus:ring-2 focus:ring-black/10 outline-none"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Tagline</label>
                                <input 
                                    type="text" 
                                    value={appSubtitle} 
                                    onChange={e => setAppSubtitle(e.target.value)}
                                    className="w-full bg-gray-50 border-none p-4 rounded-xl text-sm font-medium focus:ring-2 focus:ring-black/10 outline-none"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Theme Selector */}
                    <div>
                        <label className="text-[10px] uppercase font-bold text-gray-400 block mb-4 ml-1">Select Theme</label>
                        <div className="grid grid-cols-2 gap-3">
                            {[
                              { id: 'modern', name: 'Modern' },
                              { id: 'classic', name: 'Classic' }
                            ].map(t => (
                                <button
                                    key={t.id}
                                    onClick={() => setTheme(t.id as ThemeType)}
                                    className={`px-4 py-6 rounded-2xl text-xs font-bold transition-all border-2 text-center leading-tight ${theme === t.id ? 'bg-black text-white border-black scale-105 shadow-xl' : 'bg-gray-50 text-gray-400 border-transparent hover:border-gray-200'}`}
                                >
                                    {t.name}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-3">
                        <button onClick={handleAdminAccess} className="w-full flex items-center justify-between p-4 rounded-xl bg-gray-50 hover:bg-gray-100 transition-colors text-sm font-bold text-gray-800">
                            <div className="flex items-center gap-3">
                                <ChefHat size={20} className="text-black"/>
                                {user ? 'Chef Dashboard' : 'Chef Entrance'}
                            </div>
                            <ArrowRight size={16}/>
                        </button>
                        <button onClick={() => { setViewState('pdf-preview'); setIsSettingsOpen(false); }} className="w-full flex items-center justify-between p-4 rounded-xl bg-gray-50 hover:bg-gray-100 transition-colors text-sm font-bold text-gray-800">
                            <div className="flex items-center gap-3">
                                <FileText size={20} className="text-black"/>
                                Export PDF Menu
                            </div>
                            <ArrowRight size={16}/>
                        </button>
                    </div>
                </div>
            </div>
        )}

        {viewState === 'admin' ? (
            <AdminPanel 
                categories={categories} setCategories={setCategories}
                dishes={dishes} setDishes={setDishes}
                onClose={() => setViewState('menu-overview')}
            />
        ) : viewState === 'pdf-preview' ? (
            <PDFExportView dishes={visibleDishes} categories={visibleCategories} theme={theme} onClose={() => setViewState('menu-overview')} />
        ) : (
            <ClientView 
                categories={visibleCategories}
                dishes={visibleDishes}
                viewState={clientViewState as any}
                setViewState={setClientViewState}
                theme={theme}
                appTitle={appTitle}
                appSubtitle={appSubtitle}
                onOpenSettings={() => setIsSettingsOpen(!isSettingsOpen)}
            />
        )}
    </ThemeWrapper>
  );
};

