  return (
    <div className="bg-white dark:bg-zinc-900 rounded-[3rem] overflow-hidden shadow-[0_40px_80px_-20px_rgba(0,0,0,0.06)] flex flex-col group hover:translate-y-[-8px] transition-all duration-500 h-full border border-gray-50 dark:border-white/5 opacity-0 animate-slide-up" style={{ animationFillMode: 'forwards' }}>
      <div 
        className="relative aspect-[4/3] overflow-hidden cursor-zoom-in group/img"
        onClick={() => onImageClick(dish.image)}
