                                <div key={cat.id} className={`bg-white dark:bg-zinc-900 rounded-2xl shadow-sm hover:shadow-xl transition-all duration-300 overflow-hidden group relative animate-slide-up ${cat.isHidden ? 'opacity-75' : ''}`} style={{animationDelay: `${i*100}ms`}}>
                                    <div className="h-40 overflow-hidden relative">
                                        <img src={cat.image} className={`w-full h-full object-cover transform group-hover:scale-110 transition-transform duration-700 ${cat.isHidden ? 'grayscale' : ''}`} />
                                        {cat.isHidden && (
                                            <div className="absolute inset-0 flex items-center justify-center bg-black/10 backdrop-blur-[1px] z-[5]">
                                                 <span className="bg-black/70 text-white text-[10px] px-3 py-1 rounded-full uppercase font-black tracking-widest shadow-lg">Hidden From Menu</span>
                                            </div>
                                        )}
                                    </div>
                                    <div className="p-6">
                                        <h4 className="font-bold text-xl mb-2 flex items-center gap-2 dark:text-white">
                                            {cat.name}
                                            {cat.isHidden && <EyeOff size={14} className="text-gray-400"/>}
