                                    <div className="px-3 py-2 border-r border-gray-100 dark:border-white/10 text-gray-400">
                                        <ArrowUpDown size={16} />
                                    </div>
                                    <select 
                                        value={sortBy}
                                        onChange={(e) => setSortBy(e.target.value as any)}
                                        className="bg-transparent py-2 pl-3 pr-8 text-sm font-medium text-gray-700 dark:text-zinc-300 outline-none cursor-pointer hover:bg-gray-50 dark:hover:bg-white/5 rounded-r-xl appearance-none"
                                        style={{backgroundImage: 'none'}}
                                    >
                                        <option value="default">Default Order</option>
                                        <option value="calories-high">Calories (High → Low)</option>
                                        <option value="calories-low">Calories (Low → High)</option>
                                        <option value="name-asc">Alphabetical (A-Z)</option>
                                    </select>
                                </div>
                                <button onClick={() => { setEditingDish({ nutrition: { calories: 0, protein: 0, fat: 0, carbohydrates: 0, fiber: 0 } }); setSuggestedDesc(null); setLastImage(null); }} className="flex items-center gap-2 bg-black dark:bg-white text-white dark:text-black px-6 py-3 rounded-xl shadow-lg hover:shadow-xl hover:-translate-y-1 transition-all font-bold">
                                    <Plus size={18}/> Add New Dish
                                </button>
                            </div>
                            {categories.map(cat => {
                                const sortedDishes = dishes.filter(d => d.categoryId === cat.id).sort((a, b) => {
                                    if (sortBy === 'calories-high') return b.nutrition.calories - a.nutrition.calories;
                                    if (sortBy === 'calories-low') return a.nutrition.calories - b.nutrition.calories;
                                    if (sortBy === 'name-asc') return a.name.localeCompare(b.name);
                                    return 0;
                                });
                                return (
                                    <div 
                                        key={cat.id} 
                                        className={`bg-white/50 dark:bg-zinc-900/50 backdrop-blur-sm p-6 rounded-3xl border transition-all duration-300 ${dragOverCategoryId === cat.id ? 'border-blue-400 bg-blue-50/50 scale-[1.01]' : 'border-gray-200 dark:border-white/5'}`}
                                        onDragOver={(e) => handleDragOver(e, cat.id)}
                                        onDrop={(e) => handleDrop(e, cat.id)}
                                    >
                                        <h3 className="text-xl font-bold mb-6 ml-2 dark:text-white flex items-center gap-3">
                                            <div className="w-1.5 h-6 bg-black dark:bg-white rounded-full"></div>
                                            {cat.name}
                                        </h3>
                                        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 min-h-[100px]">
                                            {sortedDishes.length === 0 && (
                                                <div className="col-span-full border-2 border-dashed border-gray-200 dark:border-white/5 rounded-2xl flex items-center justify-center text-gray-400 text-sm font-medium h-32 text-center px-6">
                                                    No dishes in this category.<br/>Drag dishes here or add a new one.
                                                </div>
                                            )}
                                            {sortedDishes.map((dish, idx) => (
                                                <div 
                                                    key={dish.id} 
                                                    className={`bg-white dark:bg-zinc-800 rounded-2xl p-3 gap-3 shadow-sm hover:shadow-md transition-all group relative border border-transparent hover:border-gray-100 dark:hover:border-white/10 ${dish.isHidden ? 'opacity-50 grayscale' : ''}`}
                                                    draggable={sortBy === 'default'}
                                                    onDragStart={(e) => handleDragStart(e, dish.id)}
                                                    onDragEnd={handleDragEnd}
                                                    onDragOver={(e) => e.preventDefault()}
                                                    onDrop={(e) => handleDishReorder(e, dish)}
                                                >
                                                    <div className="flex items-center gap-4">
                                                        <img src={dish.image} className="w-16 h-16 rounded-xl object-cover shadow-sm" />
                                                        <div className="flex-1 min-w-0">
                                                            <div className="font-bold truncate text-gray-800 dark:text-zinc-100">{dish.name}</div>
                                                            <div className="text-[10px] text-orange-500 font-mono font-bold mt-1 uppercase tracking-wider">{dish.nutrition.calories} kcal</div>
                                                        </div>
                                                    </div>
                                                    <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-all translate-y-1 group-hover:translate-y-0 flex gap-1 bg-white/95 dark:bg-black/90 backdrop-blur-md p-1 rounded-full shadow-lg border border-black/5 dark:border-white/10 z-10">
                                                        <button 
                                                            disabled={isSyncing}
                                                            onClick={(e) => { e.stopPropagation(); toggleVisibility(dish); }} 
                                                            className="p-1.5 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full transition-colors dark:text-white disabled:opacity-50"
                                                            title={dish.isHidden ? "Show Dish" : "Hide Dish"}
                                                        >
                                                            {dish.isHidden ? <Eye size={14}/> : <EyeOff size={14}/>}
                                                        </button>
                                                        <button 
                                                            disabled={isSyncing}
                                                            onClick={(e) => { e.stopPropagation(); duplicateDish(dish); }} 
                                                            className="p-1.5 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full transition-colors dark:text-white disabled:opacity-50"
                                                            title="Duplicate Dish"
                                                        >
                                                            <Copy size={14}/>
                                                        </button>
                                                        <button onClick={() => setEditingDish(dish)} className="p-1.5 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full transition-colors dark:text-white" title="Edit Dish"><Edit size={14}/></button>
                                                        <button onClick={() => removeDish(dish.id)} className="p-1.5 hover:bg-red-50 rounded-full transition-colors text-red-500" title="Delete Dish"><Trash2 size={14}/></button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </>
            )}
        </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { CuisineCategory, Dish, ThemeType, SuitableForTag } from '../types';
import { 
  ChevronLeft, Home, Settings, Flame, Beef, Coffee, 
  Sun, Moon, Zap, Activity, Feather, Wheat, Loader2, ArrowRight,
  Droplets, X, Maximize2
} from 'lucide-react';

interface ClientViewProps {
  categories: CuisineCategory[];
  dishes: Dish[];
  viewState: {
    view: 'menu-overview' | 'dish-viewer';
    currentCategory: string | null;
    currentDishIndex: number;
  };
  setViewState: React.Dispatch<React.SetStateAction<any>>;
  theme: ThemeType;
  appTitle: string;
  appSubtitle: string;
  isOffline?: boolean;
  onOpenSettings?: () => void;
}

const ImageWithFallback = ({ src, alt, className }: { src: string; alt: string; className: string }) => {
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(true);

  return (
    <div className={`relative w-full h-full bg-[#F3F4F6] dark:bg-zinc-800 overflow-hidden ${className}`}>
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center bg-[#F3F4F6] dark:bg-zinc-800 z-10">
          <Loader2 className="animate-spin text-gray-300 dark:text-zinc-600" size={32} />
        </div>
      )}
      <img
        src={error ? 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&q=80&w=800' : src}
        alt={alt}
        className={`w-full h-full object-cover transition-all duration-1000 ${loading ? 'opacity-0 scale-110' : 'opacity-100 scale-100'}`}
        onLoad={() => setLoading(false)}
        onError={() => {
          setError(true);
          setLoading(false);
        }}
      />
    </div>
  );
};

const NutritionStat = ({ 
  label, 
  value, 
  unit = 'g', 
  isLast = false, 
  colorClass = "text-black dark:text-white",
  icon: Icon,
  animate = false
}: { 
  label: string, 
  value: number | string, 
  unit?: string, 
  isLast?: boolean, 
  colorClass?: string,
  icon?: React.ElementType,
  animate?: boolean
}) => (
  <div className={`flex-1 flex flex-col items-center px-1 ${!isLast ? 'border-r border-gray-100 dark:border-white/10' : ''}`}>
    <div className="flex items-center gap-1.5 mb-2 group">
      {Icon && <Icon size={12} className={`${animate ? 'text-orange-500' : 'text-gray-200 dark:text-zinc-700'} group-hover:text-gray-400 transition-colors`} />}
      <div className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-300 dark:text-zinc-600">{label}</div>
    </div>
    <div className={`text-2xl font-black leading-none tracking-tighter ${colorClass} ${animate ? 'animate-pulse' : ''}`}>
      {value}<span className="text-[10px] ml-0.5 opacity-40 font-bold lowercase tracking-normal">{unit}</span>
    </div>
  </div>
);

const DishCard = ({ dish, isClassic, onImageClick, index }: { dish: Dish, isClassic: boolean, onImageClick: (src: string) => void, index: number }) => {
  const allComponents = [...dish.sideDishes, ...dish.ingredients];

  return (
    <div className="bg-white dark:bg-zinc-900 rounded-[3rem] overflow-hidden shadow-[0_40px_80px_-20px_rgba(0,0,0,0.06)] flex flex-col group hover:translate-y-[-8px] transition-all duration-500 h-full border border-gray-50 dark:border-white/5 opacity-0 animate-slide-up" style={{ animationFillMode: 'forwards' }}>
      <div 
        className="relative aspect-[4/3] overflow-hidden cursor-zoom-in group/img"
        onClick={() => onImageClick(dish.image)}
      >
        <div className="absolute top-8 left-8 z-20 w-12 h-12 flex items-center justify-center bg-gray-400/20 dark:bg-black/40 backdrop-blur-md text-gray-500 dark:text-zinc-300 text-xs font-black rounded-full border border-white/20 dark:border-white/10 shadow-sm transition-transform duration-500 select-none tracking-widest">
          {(index + 1).toString().padStart(2, '0')}
        </div>

        <ImageWithFallback src={dish.image} alt={dish.name} className="group-hover:scale-110 transition-transform duration-[3s] ease-out" />

        <div className="absolute inset-0 bg-black/20 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center">
          <div className="p-4 bg-white/30 rounded-full text-white scale-75 group-hover/img:scale-100 transition-transform duration-500 border border-white/20">
            <Maximize2 size={24} />
          </div>
        </div>
      </div>

      <div className="p-12 flex-1 flex flex-col">
        <div className="mb-10">
          <h3 className={`text-5xl font-black tracking-tighter text-[#1A1A1A] dark:text-zinc-100 mb-8 leading-none ${isClassic ? 'font-serif italic' : ''}`}>
            {dish.name}
          </h3>

          <div className="flex flex-wrap items-center gap-2 mb-10">
            {allComponents.map((item, idx) => (
              <span 
                key={idx} 
                className="px-4 py-2.5 bg-gray-50/80 dark:bg-white/5 border border-gray-100/50 dark:border-white/5 rounded-full text-[9px] font-black uppercase tracking-[0.2em] text-gray-400 dark:text-zinc-500 whitespace-nowrap shadow-sm hover:bg-white dark:hover:bg-white/10 hover:shadow-md hover:border-gray-200 transition-all duration-300"
              >
                {item}
              </span>
            ))}
          </div>

          <p className="text-gray-400 dark:text-zinc-500 text-lg font-light leading-relaxed line-clamp-3 italic">
            {dish.description}
          </p>
        </div>

        <div className="mt-auto pt-10 border-t border-gray-50 dark:border-white/5">
          <div className="flex items-center justify-between">
            <NutritionStat label="Cals" value={dish.nutrition.calories} unit="" icon={Flame} colorClass="text-orange-500" animate={true} />
            <NutritionStat label="Prot" value={dish.nutrition.protein} icon={Beef} />
            <NutritionStat label="Fat" value={dish.nutrition.fat} icon={Droplets} />
            <NutritionStat label="Carb" value={dish.nutrition.carbohydrates} icon={Wheat} />
            <NutritionStat label="Fiber" value={dish.nutrition.fiber} isLast icon={Feather} />
          </div>
        </div>
      </div>
    </div>
  );
};

const Lightbox = ({ src, onClose }: { src: string; onClose: () => void }) => (
  <div 
    className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 cursor-zoom-out animate-fade-in p-6 md:p-20"
    onClick={onClose}
  >
    <button 
      className="absolute top-10 right-10 text-white/40 hover:text-white p-4 transition-all hover:rotate-90 duration-500"
      onClick={(e) => { e.stopPropagation(); onClose(); }}
    >
      <X size={40} />
    </button>
    <img 
      src={src} 
      className="max-w-full max-h-full object-contain rounded-3xl shadow-2xl border border-white/10 animate-scale-in select-none" 
      alt="Full size"
      onClick={(e) => e.stopPropagation()}
    />
  </div>
);

