                    >
                      <span className="text-[10px] font-black uppercase tracking-[0.6em] text-[#B08D57] mb-4 origin-left transition-transform duration-500 group-hover:scale-105">
                        Featured Selections
                      </span>
                      <h2 className="text-5xl font-bold tracking-tight text-slate-900 dark:text-zinc-100 mb-8 transition-colors duration-500 group-hover:text-[#B08D57] drop-shadow-sm">
                        {category.name}
                      </h2>
                      <div className="w-12 h-1 bg-slate-900/10 dark:bg-white/10 mb-10 transition-all duration-700 rounded-full group-hover:w-full group-hover:bg-[#B08D57]/20"></div>
                      <button className="px-12 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-white dark:text-black bg-slate-900 dark:bg-white shadow-2xl transition-all duration-500 hover:scale-105 active:scale-95 rounded-full group-hover:bg-[#B08D57]">
                        View Menu
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
