              <div className="text-6xl md:text-8xl text-[#D1C2A4] dark:text-zinc-400 italic font-['Playfair_Display'] font-normal leading-none -mt-4 md:-mt-6 ml-1 drop-shadow-sm">
                Selection
              </div>
            </div>
            <div className="md:mt-4 md:max-w-xs">
              <p className="text-slate-400 dark:text-zinc-500 text-xs md:text-sm font-black uppercase tracking-[0.5em] leading-relaxed">
                {appSubtitle || "A curated anthology of culinary experiences, bridging the gap between historical heritage and modern avant-garde."}
              </p>
            </div>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12 md:gap-16">
