                                            {cat.name}
                                        </h3>
                                        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 min-h-[100px]">
                                            {sortedDishes.length === 0 && (
                                                <div className="col-span-full border-2 border-dashed border-gray-200 dark:border-white/5 rounded-2xl flex items-center justify-center text-gray-400 text-sm font-medium h-32 text-center px-6">
                                                    No dishes in this category.<br/>Drag dishes here or add a new one.
                                                </div>
                                            )}
                                            {sortedDishes.map((dish, idx) => (
                                                <div 
                                                    key={dish.id} 
                                                    className={`bg-white dark:bg-zinc-800 rounded-2xl p-3 gap-3 shadow-sm hover:shadow-md transition-all group relative border border-transparent hover:border-gray-100 dark:hover:border-white/10 ${dish.isHidden ? 'opacity-50 grayscale' : ''}`}
                                                    draggable={sortBy === 'default'}
                                                    onDragStart={(e) => handleDragStart(e, dish.id)}
                                                    onDragEnd={handleDragEnd}
                                                    onDragOver={(e) => e.preventDefault()}
                                                    onDrop={(e) => handleDishReorder(e, dish)}
                                                >
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-16 h-16 rounded-xl overflow-hidden bg-gray-50 flex-shrink-0">
                                                            <img src={dish.image} className="w-full h-full object-contain shadow-sm" alt={dish.name} />
                                                        </div>
                                                        <div className="flex-1 min-w-0">
                                                            <div className="font-bold truncate text-gray-800 dark:text-zinc-100">{dish.name}</div>
                                                            <div className="text-[10px] text-orange-500 font-mono font-bold mt-1 uppercase tracking-wider">{dish.nutrition.calories} kcal</div>
                                                        </div>
                                                    </div>
                                                    <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-all translate-y-1 group-hover:translate-y-0 flex gap-1 bg-white/95 dark:bg-black/90 backdrop-blur-md p-1 rounded-full shadow-lg border border-black/5 dark:border-white/10 z-10">
                                                        <button 
                                                            disabled={isSyncing}
                                                            onClick={(e) => { e.stopPropagation(); setPromotedDishId(dish.id); }} 
                                                            className={`p-1.5 rounded-full transition-colors ${promotedDishId === dish.id ? 'bg-amber-100 text-amber-600' : 'hover:bg-gray-100 dark:hover:bg-white/10 text-gray-400'}`}
                                                            title="Feature on Landing Page"
                                                        >
                                                            <Star size={14} fill={promotedDishId === dish.id ? "currentColor" : "none"} />
                                                        </button>
                                                        <button 
                                                            disabled={isSyncing}
                                                            onClick={(e) => { e.stopPropagation(); toggleVisibility(dish); }} 
                                                            className="p-1.5 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full transition-colors dark:text-white disabled:opacity-50"
                                                            title={dish.isHidden ? "Show Dish" : "Hide Dish"}
                                                        >
                                                            {dish.isHidden ? <Eye size={14}/> : <EyeOff size={14}/>}
                                                        </button>
                                                        <button 
                                                            disabled={isSyncing}
                                                            onClick={(e) => { e.stopPropagation(); duplicateDish(dish); }} 
                                                            className="p-1.5 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full transition-colors dark:text-white disabled:opacity-50"
                                                            title="Duplicate Dish"
                                                        >
                                                            <Copy size={14}/>
                                                        </button>
                                                        <button onClick={() => setEditingDish(dish)} className="p-1.5 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full transition-colors dark:text-white" title="Edit Dish"><Edit size={14}/></button>
                                                        <button onClick={() => removeDish(dish.id)} className="p-1.5 hover:bg-red-50 rounded-full transition-colors text-red-500" title="Delete Dish"><Trash2 size={14}/></button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </>
            )}
        </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { AppState, CuisineCategory, Dish, ThemeType } from './types';
import { ThemeWrapper } from './components/ThemeWrapper';
import { AdminPanel } from './components/AdminPanel';
import { ClientView, PDFExportView } from './components/ClientView';
import { AuthForm } from './components/AuthForm';
import { Settings, ChefHat, Palette, FileText, X, ArrowRight, Sun, Moon, Star } from 'lucide-react';
import { fetchCategories, fetchDishes, supabase } from './services/supabaseService';
import { User } from '@supabase/supabase-js';

const App: React.FC = () => {
  const [categories, setCategories] = useState<CuisineCategory[]>([]);
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [showAuth, setShowAuth] = useState(false);

  const [viewState, setViewState] = useState<AppState['view']>('menu-overview');
  const [currentCategory, setCurrentCategory] = useState<string | null>(null);
  const [currentDishIndex, setCurrentDishIndex] = useState(0);
  const [theme, setTheme] = useState<ThemeType>('modern');

  const [appTitle, setAppTitle] = useState("Artisan Kitchen");
  const [appSubtitle, setAppSubtitle] = useState("Private Dining Curations");
  const [promotionTitle, setPromotionTitle] = useState("Signature Feature");
  const [philosophyTitle, setPhilosophyTitle] = useState("Nutritional Philosophy");
  const [philosophyDescription, setPhilosophyDescription] = useState("Every plate is balanced. Every calorie is considered. We believe private dining should be as nourishing as it is exquisite.");
  const [promotedDishId, setPromotedDishId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Auth State Listener
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
    });

    return () => subscription.unsubscribe();
  }, []);

  // Initial Data Fetch
  useEffect(() => {
    const loadData = async () => {
      try {
        const [cats, ds] = await Promise.all([fetchCategories(), fetchDishes()]);
        setCategories(cats);
        setDishes(ds);
        // Default promoted dish if none set
        if (ds.length > 0 && !promotedDishId) {
            setPromotedDishId(ds[0].id);
        }
        setDbError(null);
      } catch (err: any) {
        console.error("Supabase load error:", err);
        if (err.code === 'PGRST205' || err.message?.includes('not found')) {
          setDbError('DATABASE_SETUP_REQUIRED');
        } else {
          setDbError(err.message || 'Unknown database error');
        }
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  const handleAdminAccess = () => {
    if (user) {
      setViewState('admin');
      setIsSettingsOpen(false);
    } else {
      setShowAuth(true);
    }
  };

  const toggleSettings = () => {
    setIsSettingsOpen(!isSettingsOpen);
  };

  const visibleCategories = categories.filter(c => !c.isHidden);
  const visibleDishes = dishes.filter(d => 
    !d.isHidden && visibleCategories.some(c => c.id === d.categoryId)
  );

  const safeCurrentDishIndex = (currentDishIndex >= visibleDishes.length) ? 0 : currentDishIndex;

  const clientViewState = {
      view: viewState === 'menu-overview' || viewState === 'dish-viewer' ? viewState : 'menu-overview',
      currentCategory,
      currentDishIndex: safeCurrentDishIndex
  };

  const setClientViewState = (newState: any) => {
     if (typeof newState === 'function') {
         const res = newState(clientViewState);
         setViewState(res.view);
         setCurrentCategory(res.currentCategory);
         setCurrentDishIndex(res.currentDishIndex);
     } else {
         setViewState(newState.view);
         setCurrentCategory(newState.currentCategory);
         setCurrentDishIndex(newState.currentDishIndex);
     }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-white dark:bg-zinc-950 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-black/10 dark:border-white/10 border-t-black dark:border-t-white rounded-full animate-spin"></div>
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-400">Opening Kitchen</span>
        </div>
      </div>
    );
  }

  return (
    <ThemeWrapper theme={theme}>
        {showAuth && (
          <AuthForm 
            onSuccess={() => { setShowAuth(false); setViewState('admin'); setIsSettingsOpen(false); }}
            onCancel={() => setShowAuth(false)}
          />
        )}

        {/* Global Settings Panel Trigger - Positioned fixed over all views */}
        {(viewState === 'menu-overview' || viewState === 'dish-viewer') && (
            <div className="fixed top-6 right-6 z-[60] print:hidden">
                <button
                    onClick={toggleSettings}
                    className={`p-4 rounded-full shadow-2xl hover:scale-110 transition-all flex items-center justify-center ${isSettingsOpen ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-white text-black dark:bg-zinc-800 dark:text-white'}`}
                >
                    {isSettingsOpen ? <X size={24} /> : <Settings size={24} />}
                </button>
            </div>
        )}

        {/* Branding & Settings Panel */}
        {isSettingsOpen && (
            <div className="fixed top-24 right-6 z-[70] w-96 bg-white/95 dark:bg-zinc-900/95 backdrop-blur-2xl p-8 rounded-[2rem] shadow-[0_20px_60px_-10px_rgba(0,0,0,0.3)] border border-white/50 dark:border-white/5 animate-scale-in origin-top-right print:hidden max-h-[85vh] overflow-y-auto no-scrollbar">
                <div className="space-y-8">
                    <div>
                        <div className="flex items-center gap-3 mb-6">
                            <Palette size={20} className="text-gray-800 dark:text-zinc-200"/>
                            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-gray-800 dark:text-zinc-200">Visual Identity</h3>
                        </div>

                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Restaurant Name</label>
                                <input 
                                    type="text" 
                                    value={appTitle} 
                                    onChange={e => setAppTitle(e.target.value)}
                                    className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl text-sm font-bold focus:ring-2 focus:ring-black/10 dark:focus:ring-white/10 outline-none dark:text-white"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Tagline</label>
                                <input 
                                    type="text" 
                                    value={appSubtitle} 
                                    onChange={e => setAppSubtitle(e.target.value)}
                                    className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl text-sm font-medium focus:ring-2 focus:ring-black/10 dark:focus:ring-white/10 outline-none dark:text-white"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Promotion Subject</label>
                                <input 
                                    type="text" 
                                    value={promotionTitle} 
                                    onChange={e => setPromotionTitle(e.target.value)}
                                    className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl text-sm font-medium focus:ring-2 focus:ring-black/10 dark:focus:ring-white/10 outline-none dark:text-white"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Philosophy Title</label>
                                <input 
                                    type="text" 
                                    value={philosophyTitle} 
                                    onChange={e => setPhilosophyTitle(e.target.value)}
                                    className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl text-sm font-medium focus:ring-2 focus:ring-black/10 dark:focus:ring-white/10 outline-none dark:text-white"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Philosophy Text</label>
                                <textarea 
                                    value={philosophyDescription} 
                                    onChange={e => setPhilosophyDescription(e.target.value)}
                                    className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl text-sm font-light focus:ring-2 focus:ring-black/10 dark:focus:ring-white/10 outline-none dark:text-white h-24 resize-none"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Theme Selector */}
                    <div>
                        <label className="text-[10px] uppercase font-bold text-gray-400 block mb-4 ml-1">Select Theme</label>
                        <div className="grid grid-cols-3 gap-3">
                            {[
                              { id: 'modern', name: 'Modern', icon: <Sun size={14}/> },
                              { id: 'classic', name: 'Classic', icon: <FileText size={14}/> },
                              { id: 'dark', name: 'Dark', icon: <Moon size={14}/> }
                            ].map(t => (
                                <button
                                    key={t.id}
                                    onClick={() => setTheme(t.id as ThemeType)}
                                    className={`flex flex-col items-center gap-2 px-3 py-4 rounded-2xl text-[10px] font-bold transition-all border-2 text-center leading-tight ${theme === t.id ? 'bg-black text-white border-black dark:bg-white dark:text-black dark:border-white scale-105 shadow-xl' : 'bg-gray-50 text-gray-400 border-transparent hover:border-gray-200 dark:bg-white/5 dark:hover:border-white/10'}`}
                                >
                                    {t.icon}
                                    {t.name}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-3">
                        <button onClick={handleAdminAccess} className="w-full flex items-center justify-between p-4 rounded-xl bg-gray-50 dark:bg-white/5 hover:bg-gray-100 dark:hover:bg-white/10 transition-colors text-sm font-bold text-gray-800 dark:text-zinc-200">
                            <div className="flex items-center gap-3">
                                <ChefHat size={20} className="text-black dark:text-white"/>
                                {user ? 'Chef Dashboard' : 'Chef Entrance'}
                            </div>
                            <ArrowRight size={16}/>
                        </button>
                        <button onClick={() => { setViewState('pdf-preview'); setIsSettingsOpen(false); }} className="w-full flex items-center justify-between p-4 rounded-xl bg-gray-50 dark:bg-white/5 hover:bg-gray-100 dark:hover:bg-white/10 transition-colors text-sm font-bold text-gray-800 dark:text-zinc-200">
                            <div className="flex items-center gap-3">
                                <FileText size={20} className="text-black dark:text-white"/>
                                Export PDF Menu
                            </div>
                            <ArrowRight size={16}/>
                        </button>
                    </div>
                </div>
            </div>
        )}

        {viewState === 'admin' ? (
            <AdminPanel 
                categories={categories} setCategories={setCategories}
                dishes={dishes} setDishes={setDishes}
                promotedDishId={promotedDishId}
                setPromotedDishId={setPromotedDishId}
                onClose={() => setViewState('menu-overview')}
            />
        ) : viewState === 'pdf-preview' ? (
            <PDFExportView dishes={visibleDishes} categories={visibleCategories} theme={theme} onClose={() => setViewState('menu-overview')} />
        ) : (
            <ClientView 
                categories={visibleCategories}
                dishes={visibleDishes}
                viewState={clientViewState as any}
                setViewState={setClientViewState}
                theme={theme}
                appTitle={appTitle}
                appSubtitle={appSubtitle}
                promotionTitle={promotionTitle}
                philosophyTitle={philosophyTitle}
                philosophyDescription={philosophyDescription}
                promotedDishId={promotedDishId}
            />
        )}
    </ThemeWrapper>
  );
};

export default App;

