            <NutritionStat label="Carb" value={dish.nutrition.carbohydrates} icon={Wheat} />
            <NutritionStat label="Fiber" value={dish.nutrition.fiber} isLast icon={Feather} />
          </div>
        </div>
      </div>
    </div>
  );
