            <button 
              onClick={handleNextDish}
              className="absolute right-12 z-30 w-20 h-20 rounded-full border border-gray-200 dark:border-white/10 flex items-center justify-center hover:bg-black hover:text-white dark:hover:bg-white dark:hover:text-black transition-all bg-white/50 dark:bg-black/50 backdrop-blur-xl group"
