                      index={idx}
                      isActive={idx === viewState.currentDishIndex}
                    />
                  </div>
                ))}
              </div>
            </div>

            {/* Pagination Dots */}
            <div className="absolute bottom-12 flex gap-3">
              {currentCategoryDishes.map((_, i) => (
                <button 
                  key={i}
                  onClick={() => setViewState((p: any) => ({...p, currentDishIndex: i}))}
