                                <input type="file" className="hidden" accept="image/*" onChange={(e) => handleFileUpload(e, (base64) => setEditingCategory(p => ({...p, image: base64})))} />
                            </label>
                            <button onClick={handleGenerateCategoryImage} disabled={!editingCategory?.name || isGeneratingCategoryImg} className="flex-1 bg-purple-600 text-white px-4 py-2 rounded-lg hover:bg-purple-700 transition-colors flex items-center justify-center gap-2 text-xs font-bold uppercase tracking-wider disabled:opacity-50 shadow-md">
                                {isGeneratingCategoryImg ? <Loader2 className="animate-spin" size={14} /> : <Wand2 size={14} />} AI
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Right side: Acknowledgment Details */}
            <div className="bg-gray-50 dark:bg-white/5 p-6 rounded-3xl space-y-6">
                <h4 className="flex items-center gap-2 font-black uppercase tracking-widest text-xs text-[#B08D57]">
                    <FileText size={16} /> Menu Acknowledgment
                </h4>

                <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Review Date & Time</label>
                    <input 
                        type="datetime-local" 
                        className="w-full bg-white dark:bg-black/20 border border-gray-200 dark:border-white/10 p-3 rounded-lg focus:ring-2 focus:ring-[#B08D57]/20 outline-none dark:text-white"
                        value={editingCategory?.acknowledgment?.reviewDateTime || ''}
                        onChange={e => setEditingCategory(p => ({
                            ...p, 
                            acknowledgment: { ...(p.acknowledgment || { notes: '', reviewers: [] }), reviewDateTime: e.target.value }
                        }))}
                    />
                </div>

                <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Review Statement</label>
                    <textarea 
                        className="w-full bg-white dark:bg-black/20 border border-gray-200 dark:border-white/10 p-3 rounded-lg focus:ring-2 focus:ring-[#B08D57]/20 outline-none dark:text-white h-32 resize-none text-sm italic"
                        placeholder="Formal review content..."
                        value={editingCategory?.acknowledgment?.notes || ''}
                        onChange={e => setEditingCategory(p => ({
                            ...p, 
                            acknowledgment: { ...(p.acknowledgment || { reviewDateTime: '', reviewers: [] }), notes: e.target.value }
                        }))}
                    />
                </div>

                <div className="space-y-4">
                    <div className="flex items-center justify-between">
                        <label className="text-xs font-bold uppercase tracking-widest text-gray-400">Reviewers & Signatures</label>
                        <button onClick={addReviewer} className="p-1.5 bg-black dark:bg-white text-white dark:text-black rounded-lg hover:scale-105 transition-all">
                            <Plus size={14} />
                        </button>
                    </div>

                    <div className="space-y-4 max-h-[300px] overflow-y-auto pr-2 no-scrollbar">
                        {(editingCategory?.acknowledgment?.reviewers || []).map((reviewer, idx) => (
                            <div key={idx} className="bg-white dark:bg-zinc-800 p-4 rounded-xl border border-gray-100 dark:border-white/10 relative group/reviewer">
                                <button onClick={() => removeReviewer(idx)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover/reviewer:opacity-100 transition-opacity">
                                    <X size={10} />
                                </button>
                                <div className="grid grid-cols-2 gap-3 mb-3">
                                    <input 
                                        type="text" 
                                        placeholder="Full Name" 
                                        className="text-[10px] font-bold uppercase p-2 bg-gray-50 dark:bg-black/20 rounded border-none outline-none dark:text-white"
                                        value={reviewer.name}
                                        onChange={e => updateReviewer(idx, 'name', e.target.value)}
                                    />
                                    <input 
                                        type="text" 
                                        placeholder="Position" 
                                        className="text-[10px] font-bold uppercase p-2 bg-gray-50 dark:bg-black/20 rounded border-none outline-none dark:text-white"
                                        value={reviewer.position}
                                        onChange={e => updateReviewer(idx, 'position', e.target.value)}
                                    />
                                </div>
                                <div className="flex items-center gap-4">
                                    <div className="flex-1 h-12 border-2 border-dashed border-gray-100 dark:border-white/10 rounded flex items-center justify-center overflow-hidden bg-gray-50 dark:bg-black/10">
                                        {reviewer.signature ? (
                                            <img src={reviewer.signature} className="max-h-full object-contain" />
                                        ) : (
                                            <PenTool size={16} className="text-gray-200" />
                                        )}
                                    </div>
                                    <label className="shrink-0 cursor-pointer p-3 bg-gray-100 dark:bg-white/5 rounded-lg hover:bg-gray-200 transition-colors">
                                        <Upload size={14} className="dark:text-white" />
                                        <input type="file" className="hidden" accept="image/*" onChange={(e) => handleFileUpload(e, (base64) => updateReviewer(idx, 'signature', base64))} />
                                    </label>
                                </div>
                            </div>
                        ))}
                        {(!editingCategory?.acknowledgment?.reviewers || editingCategory.acknowledgment.reviewers.length === 0) && (
                            <div className="text-center py-6 text-gray-300 dark:text-zinc-600 italic text-[10px] uppercase tracking-widest border-2 border-dashed border-gray-100 dark:border-white/5 rounded-2xl">
                                No reviewers assigned
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>

        <div className="flex justify-end gap-3 mt-8 pt-6 border-t border-gray-100 dark:border-white/10">
            <button onClick={() => setEditingCategory(null)} className="px-6 py-3 text-gray-500 hover:bg-gray-100 dark:hover:bg-white/10 rounded-xl transition-colors">Cancel</button>
            <button onClick={saveCategory} disabled={isSyncing} className="px-8 py-3 bg-black dark:bg-white text-white dark:text-black rounded-xl shadow-lg hover:shadow-xl hover:scale-105 transition-all font-medium flex items-center gap-2">
                {isSyncing && <Loader2 size={16} className="animate-spin" />}
                Save Category
            </button>
        </div>
    </div>
  );

  const saveDish = async () => {
    if (!editingDish?.name || !editingDish.categoryId || !editingDish.image || !editingDish.nutrition) return;

    const dishToSave = {
        ...editingDish,
        id: editingDish.id || generateId(),
        description: editingDish.description || '',
        sideDishes: editingDish.sideDishes || [],
        ingredients: editingDish.ingredients || [],
        suitableFor: editingDish.suitableFor || [],
        isHidden: editingDish.isHidden || false
    } as Dish;

    setIsSyncing(true);
    try {
        await upsertDish(dishToSave);
        if (editingDish.id) {
          setDishes(prev => prev.map(d => d.id === dishToSave.id ? dishToSave : d));
        } else {
          setDishes(prev => [...prev, dishToSave]);
        }
        setEditingDish(null);
        setSuggestedDesc(null);
        setLastImage(null);
    } catch (e) {
        console.error("Failed to save dish:", e);
        alert("Database error.");
    } finally {
        setIsSyncing(false);
    }
  };

  const removeDish = async (id: string) => {
    setIsSyncing(true);
    try {
        await deleteDishFromDB(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        if (promotedDishId === id) setPromotedDishId(null);
    } catch (e) {
        console.error(e);
    } finally {
        setIsSyncing(false);
    }
  }

  const renderDishEditor = () => (
    <div className="bg-white/95 dark:bg-zinc-900/95 backdrop-blur-2xl p-8 rounded-2xl shadow-2xl max-w-5xl mx-auto h-[85vh] overflow-y-auto border border-white/50 dark:border-white/5 animate-scale-in no-scrollbar">
        <h3 className="text-2xl font-bold mb-8 text-gray-800 dark:text-gray-100 flex items-center gap-3">
            {editingDish?.id ? 'Edit Dish' : 'New Dish'}
            <span className="text-xs font-normal text-gray-400 dark:text-gray-500 bg-gray-100 dark:bg-white/5 px-2 py-1 rounded-full border dark:border-white/10">AI Enabled</span>
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
            <div className="space-y-6">
                 <div className="responsive-image bg-gray-50 dark:bg-white/5 rounded-2xl overflow-hidden relative group border-2 border-dashed border-gray-200 dark:border-white/10 hover:border-black/20 dark:hover:border-white/20 transition-colors">
                    {editingDish?.image ? (
                        <img src={editingDish.image} alt={editingDish.name} />
                    ) : (
                        <div className="w-full h-full flex flex-col items-center justify-center text-gray-400">
                             <ImageIcon size={48} className="mb-2 opacity-50" />
                             <span>No Image Selected</span>
                        </div>
                    )}

                    {lastImage && (
                        <button onClick={(e) => { e.preventDefault(); e.stopPropagation(); if (lastImage) setEditingDish(p => ({ ...p, image: lastImage })); setLastImage(null); }} className="absolute top-4 left-4 z-30 p-2.5 bg-white/80 dark:bg-black/80 hover:bg-white dark:hover:bg-black text-gray-700 dark:text-gray-300 hover:text-black dark:hover:text-white rounded-xl shadow-lg border border-white/40 dark:border-white/10 backdrop-blur-md transition-all hover:scale-105" title="Undo last change">
                            <Undo2 size={20} />
                        </button>
                    )}

                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-sm">
                        <label className="cursor-pointer text-white flex flex-col items-center hover:scale-110 transition-transform">
                            <Upload className="w-10 h-10 mb-2" />
                            <span className="font-medium">Upload New</span>
                            <input type="file" className="hidden" accept="image/*" onChange={(e) => handleFileUpload(e, (base64) => { setLastImage(editingDish?.image || null); setEditingDish(p => ({...p, image: base64})); })} />
                        </label>
                    </div>
                    {isEnhancing && (
                        <div className="absolute inset-0 bg-white/90 dark:bg-black/90 flex flex-col items-center justify-center z-20">
                            <Loader2 className="animate-spin text-blue-600 mb-2" size={40} />
                            <span className="text-sm font-medium text-blue-900 dark:text-blue-300 animate-pulse">Enhancing with Gemini...</span>
                        </div>
                    )}
                 </div>

                 {editingDish?.image && (
                     <div className="bg-blue-50/50 dark:bg-blue-900/10 p-6 rounded-2xl border border-blue-100 dark:border-blue-900/30">
                         <h4 className="font-bold text-blue-900 dark:text-blue-300 flex items-center gap-2 mb-4 text-sm uppercase tracking-wide"><Wand2 size={16}/> AI Studio Tools</h4>
                         <div className="grid grid-cols-2 gap-3 mb-6">
                             <button onClick={() => handleAIImageEnhance('lighting')} className="text-xs font-medium bg-white dark:bg-zinc-800 text-blue-900 dark:text-blue-300 border border-blue-100 dark:border-blue-900/30 p-3 rounded-xl hover:bg-blue-600 dark:hover:bg-blue-500 hover:text-white dark:hover:text-white hover:border-transparent transition-all shadow-sm">Improve Lighting</button>
                             <button onClick={() => handleAIImageEnhance('color')} className="text-xs font-medium bg-white dark:bg-zinc-800 text-blue-900 dark:text-blue-300 border border-blue-100 dark:border-blue-900/30 p-3 rounded-xl hover:bg-blue-600 dark:hover:bg-blue-500 hover:text-white dark:hover:text-white hover:border-transparent transition-all shadow-sm">Enhance Colors</button>
                             <button onClick={() => handleAIImageEnhance('upscale')} className="text-xs font-medium bg-white dark:bg-zinc-800 text-blue-900 dark:text-blue-300 border border-blue-100 dark:border-blue-900/30 p-3 rounded-xl hover:bg-blue-600 dark:hover:bg-blue-500 hover:text-white dark:hover:text-white hover:border-transparent transition-all shadow-sm flex items-center justify-center gap-2"><Maximize size={12}/> Upscale AI</button>
                             <button onClick={() => handleAIImageEnhance('remove-bg')} className="text-xs font-medium bg-white dark:bg-zinc-800 text-blue-900 dark:text-blue-300 border border-blue-100 dark:border-blue-900/30 p-3 rounded-xl hover:bg-blue-600 dark:hover:bg-blue-500 hover:text-white dark:hover:text-white hover:border-transparent transition-all shadow-sm">Remove Background</button>
                         </div>
                     </div>
                 )}
            </div>

            <div className="space-y-6">
                 <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Category</label>
                    <select className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl outline-none dark:text-white" value={editingDish?.categoryId || ''} onChange={e => setEditingDish(p => ({...p, categoryId: e.target.value}))}>
                        <option value="">Select Category</option>
                        {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                 </div>
                 <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Dish Name</label>
                    <input type="text" className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl outline-none font-medium text-lg dark:text-white" value={editingDish?.name || ''} onChange={e => setEditingDish(p => ({...p, name: e.target.value}))} />
                 </div>
                 <div className="bg-orange-50 dark:bg-orange-950/20 p-6 rounded-2xl">
                     <label className="block text-xs font-bold uppercase tracking-widest text-orange-600 dark:text-orange-400 mb-2">Calories (kcal)</label>
                     <input type="number" className="bg-transparent font-black text-3xl outline-none dark:text-white" value={editingDish?.nutrition?.calories || 0} onChange={e => setEditingDish(p => ({...p, nutrition: {...p.nutrition!, calories: parseInt(e.target.value) || 0}}))} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                     <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-xl">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest block mb-1">Protein (g)</label>
                        <input type="number" className="bg-transparent font-bold text-xl outline-none dark:text-white w-full" value={editingDish?.nutrition?.protein || 0} onChange={e => setEditingDish(p => ({...p, nutrition: {...p.nutrition!, protein: parseInt(e.target.value) || 0}}))} />
                     </div>
                     <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-xl">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest block mb-1">Fat (g)</label>
                        <input type="number" className="bg-transparent font-bold text-xl outline-none dark:text-white w-full" value={editingDish?.nutrition?.fat || 0} onChange={e => setEditingDish(p => ({...p, nutrition: {...p.nutrition!, fat: parseInt(e.target.value) || 0}}))} />
                     </div>
                 </div>
            </div>
        </div>

        <div className="flex justify-end gap-4 mt-8 pt-6 border-t border-gray-200 dark:border-white/10">
            <button onClick={() => { setEditingDish(null); setSuggestedDesc(null); setLastImage(null); }} className="px-8 py-4 text-gray-500 hover:bg-gray-100 dark:hover:bg-white/10 rounded-xl transition-colors">Cancel</button>
            <button onClick={saveDish} disabled={isSyncing} className="px-10 py-4 bg-black dark:bg-white text-white dark:text-black rounded-xl shadow-xl hover:shadow-2xl hover:scale-105 transition-all font-bold tracking-wide flex items-center gap-2">
                {isSyncing && <Loader2 size={18} className="animate-spin" />} Save Dish
            </button>
        </div>
    </div>
  );

  const handleAIImageEnhance = async (type: 'lighting' | 'color' | 'remove-bg' | 'replace-bg' | 'upscale' | 'zoom-in' | 'zoom-out', modifier?: string) => {
    if (!editingDish?.image) return;
    setLastImage(editingDish.image); 
    setIsEnhancing(true);
    try {
      const enhanced = await enhanceDishImage(editingDish.image, type, modifier);
      if (enhanced) {
        setEditingDish(prev => ({ ...prev, image: enhanced }));
      }
    } catch (e) { console.error(e); } finally { setIsEnhancing(false); }
  };

  const handleAutoDescription = async () => {
      if(!editingDish?.name) return;
      setIsGeneratingDesc(true);
      try {
        const desc = await suggestDishDescription(editingDish.name, editingDish.ingredients || []);
        setSuggestedDesc(desc);
        setEditingDish(prev => ({ ...prev, description: desc }));
      } catch (e) { console.error(e); } finally { setIsGeneratingDesc(false); }
  }

  const handleDragStart = (e: React.DragEvent, dishId: string) => { e.dataTransfer.setData('dishId', dishId); e.dataTransfer.effectAllowed = 'move'; };
  const handleDragOver = (e: React.DragEvent, categoryId: string) => { e.preventDefault(); setDragOverCategoryId(categoryId); };
  const handleDrop = async (e: React.DragEvent, categoryId: string) => {
      e.preventDefault();
      const dishId = e.dataTransfer.getData('dishId');
      if (dishId) {
          const dish = dishes.find(d => d.id === dishId);
          if (dish) {
              const updated = { ...dish, categoryId };
              setIsSyncing(true);
              try { await upsertDish(updated); setDishes(prev => prev.map(d => d.id === dishId ? updated : d)); } catch (e) { console.error(e); } finally { setIsSyncing(false); }
          }
      }
      setDragOverCategoryId(null);
  };

  return (
    <div className="fixed inset-0 bg-black/5 dark:bg-black/40 z-50 overflow-y-auto backdrop-blur-sm animate-fade-in">
        <div className="bg-white/80 dark:bg-zinc-950/80 backdrop-blur-md border-b border-white/20 dark:border-white/5 px-10 py-6 flex justify-between items-center sticky top-0 z-20 shadow-sm">
            <div className="flex items-center gap-3">
                 <div className={`w-3 h-3 rounded-full ${isSyncing ? 'bg-amber-500 animate-pulse' : 'bg-green-500'}`}></div>
                 <h1 className="text-xl font-bold tracking-tight dark:text-white">Chef Dashboard</h1>
            </div>
            <div className="flex items-center gap-4">
              <button onClick={handleLogOut} className="flex items-center gap-2 px-4 py-2 text-sm font-bold text-gray-500 hover:text-red-600 transition-colors"><LogOut size={18} /> Log Out</button>
              <button onClick={onClose} className="p-2 bg-gray-100 dark:bg-white/5 rounded-full hover:bg-gray-200 dark:hover:bg-white/10 transition-colors dark:text-white"><X size={20}/></button>
            </div>
        </div>

        <div className="max-w-7xl mx-auto p-10">
            {editingCategory ? renderCategoryEditor() : editingDish ? renderDishEditor() : (
                <>
                    <div className="flex gap-8 mb-10 border-b border-gray-200 dark:border-white/10">
                        <button className={`pb-4 px-2 text-lg transition-all ${activeTab === 'categories' ? 'border-b-2 border-black dark:border-white font-bold dark:text-white' : 'text-gray-400 hover:text-gray-600'}`} onClick={() => setActiveTab('categories')}>Categories</button>
                        <button className={`pb-4 px-2 text-lg transition-all ${activeTab === 'dishes' ? 'border-b-2 border-black dark:border-white font-bold dark:text-white' : 'text-gray-400 hover:text-gray-600'}`} onClick={() => setActiveTab('dishes')}>Dishes</button>
                    </div>

                    {activeTab === 'categories' ? (
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                            <button onClick={() => setEditingCategory({})} className="h-64 border-2 border-dashed border-gray-300 dark:border-white/10 rounded-2xl flex flex-col items-center justify-center text-gray-400 hover:border-black dark:hover:border-white hover:text-black dark:hover:text-white hover:bg-gray-50 dark:hover:bg-white/5 transition-all group">
                                <div className="p-4 bg-gray-100 dark:bg-white/5 rounded-full mb-4 group-hover:scale-110 transition-transform"><Plus size={32} /></div>
                                <span className="font-medium">New Category</span>
                            </button>
                            {categories.map((cat, i) => (
                                <div key={cat.id} className={`bg-white dark:bg-zinc-900 rounded-2xl shadow-sm hover:shadow-xl transition-all duration-300 overflow-hidden group relative animate-slide-up ${cat.isHidden ? 'opacity-75' : ''}`} style={{animationDelay: `${i*100}ms`}}>
                                    <div className="responsive-image bg-gray-50">
                                        <img src={cat.image} alt={cat.name} className={`transform group-hover:scale-110 transition-transform duration-700 ${cat.isHidden ? 'grayscale' : ''}`} />
                                    </div>
                                    <div className="p-6">
                                        <h4 className="font-bold text-xl mb-2 flex items-center gap-2 dark:text-white">{cat.name}</h4>
                                        <p className="text-sm text-gray-500 dark:text-zinc-400 line-clamp-2 leading-relaxed">{cat.description}</p>
                                    </div>
                                    <div className="absolute top-3 right-3 flex gap-2 opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0 z-10">
                                        <button onClick={() => setEditingCategory(cat)} className="p-2.5 bg-white/95 dark:bg-black/80 backdrop-blur-md rounded-full shadow-lg hover:bg-black dark:hover:bg-white hover:text-white dark:hover:text-black transition-all hover:scale-110 border border-black/5 dark:border-white/10"><Edit size={16}/></button>
                                        <button onClick={() => removeCategory(cat.id)} className="p-2.5 bg-white/95 dark:bg-black/80 backdrop-blur-md text-red-600 rounded-full shadow-lg hover:bg-red-500 hover:text-white transition-all hover:scale-110 border border-black/5 dark:border-white/10"><Trash2 size={16}/></button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="space-y-10">
                            <button onClick={() => setEditingDish({ nutrition: { calories: 0, protein: 0, fat: 0, carbohydrates: 0, fiber: 0 } })} className="flex items-center gap-2 bg-black dark:bg-white text-white dark:text-black px-6 py-3 rounded-xl shadow-lg hover:scale-105 transition-all font-bold"><Plus size={18}/> Add New Dish</button>
                            {categories.map(cat => (
                                <div key={cat.id} className={`bg-white/50 dark:bg-zinc-900/50 backdrop-blur-sm p-6 rounded-3xl border transition-all duration-300 ${dragOverCategoryId === cat.id ? 'border-blue-400 bg-blue-50/50' : 'border-gray-200 dark:border-white/5'}`} onDragOver={(e) => handleDragOver(e, cat.id)} onDrop={(e) => handleDrop(e, cat.id)}>
                                    <h3 className="text-xl font-bold mb-6 dark:text-white flex items-center gap-3"><div className="w-1.5 h-6 bg-black dark:bg-white rounded-full"></div>{cat.name}</h3>
                                    <div className="grid grid-cols-1 md:grid-cols-4 gap-6 min-h-[100px]">
                                        {dishes.filter(d => d.categoryId === cat.id).map((dish) => (
                                            <div key={dish.id} className="bg-white dark:bg-zinc-800 rounded-2xl p-3 gap-3 shadow-sm hover:shadow-md transition-all group relative border border-transparent hover:border-gray-100 dark:hover:border-white/10" draggable onDragStart={(e) => handleDragStart(e, dish.id)}>
                                                <div className="flex items-center gap-4">
                                                    <div className="w-16 h-16 rounded-xl overflow-hidden bg-gray-50 flex-shrink-0"><img src={dish.image} className="w-full h-full object-contain" alt={dish.name} /></div>
                                                    <div className="flex-1 min-w-0"><div className="font-bold truncate text-gray-800 dark:text-zinc-100">{dish.name}</div><div className="text-[10px] text-orange-500 font-mono font-bold mt-1 uppercase tracking-wider">{dish.nutrition.calories} kcal</div></div>
                                                </div>
                                                <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-all flex gap-1 z-10">
                                                    <button onClick={() => setEditingDish(dish)} className="p-1.5 bg-white dark:bg-black rounded-full shadow-lg border dark:border-white/10"><Edit size={14}/></button>
                                                    <button onClick={() => removeDish(dish.id)} className="p-1.5 bg-white dark:bg-black text-red-500 rounded-full shadow-lg border dark:border-white/10"><Trash2 size={14}/></button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </>
            )}
        </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { CuisineCategory, Dish, ThemeType, SuitableForTag, Acknowledgment } from '../types';
import { 
  ChevronLeft, Home, Settings, Flame, Beef, Coffee, 
  Sun, Moon, Zap, Activity, Feather, Wheat, Loader2, ArrowRight,
  Droplets, X, Maximize2, Clock, ChevronRight, FileText, Calendar, CheckCircle
} from 'lucide-react';

interface ClientViewProps {
  categories: CuisineCategory[];
  dishes: Dish[];
  viewState: {
    view: 'menu-overview' | 'dish-viewer' | 'acknowledgment';
    currentCategory: string | null;
    currentDishIndex: number;
  };
