              <span key={idx} className="px-4 py-2.5 bg-gray-50/80 dark:bg-white/5 border border-gray-100/50 dark:border-white/5 rounded-full text-[9px] font-black uppercase tracking-[0.2em] text-gray-400 dark:text-zinc-500 whitespace-nowrap shadow-sm hover:bg-white dark:hover:bg-white/10 transition-all duration-300">{item}</span>
