                <button onClick={handlePrevCategory} className="w-12 h-12 flex items-center justify-center rounded-full border border-gray-200 dark:border-white/10 hover:bg-black hover:text-white dark:hover:bg-white dark:hover:text-black transition-all"><ChevronLeft size={20} /></button>
                <button onClick={handleNextCategory} className="w-12 h-12 flex items-center justify-center rounded-full border border-gray-200 dark:border-white/10 hover:bg-black hover:text-white dark:hover:bg-white dark:hover:text-black transition-all"><ChevronRight size={20} /></button>
