                {categories.map((category, idx) => {
                  const isActive = idx === activeCategoryIndex;
                  return (
                    <div key={category.id} className={`w-[420px] shrink-0 transition-all duration-1000 ${isActive ? 'scale-100 opacity-100 z-10' : 'scale-90 opacity-40 blur-[1px]'}`} onClick={() => setActiveCategoryIndex(idx)}>
