import React, { useState, useEffect } from 'react';
import { AppState, CuisineCategory, Dish, ThemeType } from './types';
import { ThemeWrapper } from './components/ThemeWrapper';
import { AdminPanel } from './components/AdminPanel';
import { ClientView, PDFExportView } from './components/ClientView';
import { AuthForm } from './components/AuthForm';
import { Settings, ChefHat, Palette, FileText, X, ArrowRight, Sun, Moon, Star } from 'lucide-react';
import { fetchCategories, fetchDishes, supabase } from './services/supabaseService';
import { User } from '@supabase/supabase-js';

const App: React.FC = () => {
  const [categories, setCategories] = useState<CuisineCategory[]>([]);
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [showAuth, setShowAuth] = useState(false);

  const [viewState, setViewState] = useState<AppState['view']>('menu-overview');
  const [currentCategory, setCurrentCategory] = useState<string | null>(null);
  const [currentDishIndex, setCurrentDishIndex] = useState(0);
  const [theme, setTheme] = useState<ThemeType>('modern');

  const [appTitle, setAppTitle] = useState("Artisan Kitchen");
  const [appSubtitle, setAppSubtitle] = useState("Private Dining Curations");
  const [promotionTitle, setPromotionTitle] = useState("Signature Feature");
  const [philosophyTitle, setPhilosophyTitle] = useState("Nutritional Philosophy");
  const [philosophyDescription, setPhilosophyDescription] = useState("Every plate is balanced. Every calorie is considered. We believe private dining should be as nourishing as it is exquisite.");
  const [promotedDishId, setPromotedDishId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Auth State Listener
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
    });

    return () => subscription.unsubscribe();
  }, []);

  // Initial Data Fetch
  useEffect(() => {
    const loadData = async () => {
      try {
        const [cats, ds] = await Promise.all([fetchCategories(), fetchDishes()]);
        setCategories(cats);
        setDishes(ds);
        if (ds.length > 0 && !promotedDishId) {
            setPromotedDishId(ds[0].id);
        }
        setDbError(null);
      } catch (err: any) {
        console.error("Supabase load error:", err);
        setDbError(err.message || 'Unknown database error');
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  const handleAdminAccess = () => {
    if (user) {
      setViewState('admin');
      setIsSettingsOpen(false);
    } else {
      setShowAuth(true);
    }
  };

  const toggleSettings = () => {
    setIsSettingsOpen(!isSettingsOpen);
  };

  const visibleCategories = categories.filter(c => !c.isHidden);
  const visibleDishes = dishes.filter(d => 
    !d.isHidden && visibleCategories.some(c => c.id === d.categoryId)
  );

  const safeCurrentDishIndex = (currentDishIndex >= visibleDishes.length) ? 0 : currentDishIndex;

  const clientViewState = {
      view: viewState === 'menu-overview' || viewState === 'dish-viewer' ? viewState : 'menu-overview',
      currentCategory,
      currentDishIndex: safeCurrentDishIndex
  };

  const setClientViewState = (newState: any) => {
     if (typeof newState === 'function') {
         const res = newState(clientViewState);
         setViewState(res.view);
         setCurrentCategory(res.currentCategory);
         setCurrentDishIndex(res.currentDishIndex);
     } else {
         setViewState(newState.view);
         setCurrentCategory(newState.currentCategory);
         setCurrentDishIndex(newState.currentDishIndex);
     }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-white dark:bg-zinc-950 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-black/10 dark:border-white/10 border-t-black dark:border-t-white rounded-full animate-spin"></div>
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-400">Opening Kitchen</span>
        </div>
      </div>
    );
  }

  return (
    <ThemeWrapper theme={theme}>
        {showAuth && (
          <AuthForm 
            onSuccess={() => { setShowAuth(false); setViewState('admin'); setIsSettingsOpen(false); }}
            onCancel={() => setShowAuth(false)}
          />
        )}

        {(viewState === 'menu-overview' || viewState === 'dish-viewer') && (
            <div className="fixed top-6 right-6 z-[60] print:hidden">
                <button
                    onClick={toggleSettings}
                    className={`p-4 rounded-full shadow-2xl hover:scale-110 transition-all flex items-center justify-center ${isSettingsOpen ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-white text-black dark:bg-zinc-800 dark:text-white'}`}
                >
                    {isSettingsOpen ? <X size={24} /> : <Settings size={24} />}
                </button>
            </div>
        )}

        {isSettingsOpen && (
            <div className="fixed top-24 right-6 z-[70] w-96 bg-white/95 dark:bg-zinc-900/95 backdrop-blur-2xl p-8 rounded-[2rem] shadow-[0_20px_60px_-10px_rgba(0,0,0,0.3)] border border-white/50 dark:border-white/5 animate-scale-in origin-top-right print:hidden max-h-[85vh] overflow-y-auto no-scrollbar">
                <div className="space-y-8">
                    <div>
                        <div className="flex items-center gap-3 mb-6">
                            <Palette size={20} className="text-gray-800 dark:text-zinc-200"/>
                            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-gray-800 dark:text-zinc-200">Visual Identity</h3>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Restaurant Name</label>
                                <input type="text" value={appTitle} onChange={e => setAppTitle(e.target.value)} className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl text-sm font-bold outline-none dark:text-white" />
                            </div>
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Tagline</label>
                                <input type="text" value={appSubtitle} onChange={e => setAppSubtitle(e.target.value)} className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl text-sm font-medium outline-none dark:text-white" />
                            </div>
                        </div>
                    </div>
                    <div className="space-y-3">
                        <button onClick={handleAdminAccess} className="w-full flex items-center justify-between p-4 rounded-xl bg-gray-50 dark:bg-white/5 hover:bg-gray-100 transition-colors text-sm font-bold text-gray-800 dark:text-zinc-200">
                            <div className="flex items-center gap-3"><ChefHat size={20} className="text-black dark:text-white"/>{user ? 'Chef Dashboard' : 'Chef Entrance'}</div>
                            <ArrowRight size={16}/>
                        </button>
                    </div>
                </div>
            </div>
        )}

        {viewState === 'admin' ? (
            <AdminPanel 
                categories={categories} setCategories={setCategories}
                dishes={dishes} setDishes={setDishes}
                promotedDishId={promotedDishId}
                setPromotedDishId={setPromotedDishId}
                onClose={() => setViewState('menu-overview')}
            />
        ) : viewState === 'pdf-preview' ? (
            <PDFExportView dishes={visibleDishes} categories={visibleCategories} theme={theme} onClose={() => setViewState('menu-overview')} />
        ) : (
            <ClientView 
                categories={visibleCategories}
                dishes={visibleDishes}
                viewState={clientViewState as any}
                setViewState={setClientViewState}
                theme={theme}
                appTitle={appTitle}
                appSubtitle={appSubtitle}
                promotionTitle={promotionTitle}
                philosophyTitle={philosophyTitle}
                philosophyDescription={philosophyDescription}
                promotedDishId={promotedDishId}
            />
        )}
    </ThemeWrapper>
  );
};

export default App;

import React, { useState } from 'react';
import { CuisineCategory, Dish, SuitableForTag, SUITABLE_FOR_OPTIONS } from '../types';
import { enhanceDishImage, suggestDishDescription, generateImageFromText } from '../services/geminiService';
import { upsertCategory, deleteCategoryFromDB, upsertDish, deleteDishFromDB, signOut } from '../services/supabaseService';
import { Plus, Trash2, Edit, Upload, Wand2, X, Save, Image as ImageIcon, Loader2, Sparkles, Copy, Eye, EyeOff, Undo2, GripVertical, Sun, Moon, Coffee, Utensils, Zap, Activity, Feather, Beef, Wheat, Maximize, ZoomIn, ZoomOut, ArrowUpDown, LogOut, Palette, Star } from 'lucide-react';

interface AdminPanelProps {
  categories: CuisineCategory[];
  setCategories: React.Dispatch<React.SetStateAction<CuisineCategory[]>>;
  dishes: Dish[];
  setDishes: React.Dispatch<React.SetStateAction<Dish[]>>;
  promotedDishId: string | null;
  setPromotedDishId: React.Dispatch<React.SetStateAction<string | null>>;
  onClose: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ categories, setCategories, dishes, setDishes, promotedDishId, setPromotedDishId, onClose }) => {
  const [activeTab, setActiveTab] = useState<'categories' | 'dishes'>('categories');
  const [sortBy, setSortBy] = useState<'default' | 'calories-high' | 'calories-low' | 'name-asc'>('default');
  const [isSyncing, setIsSyncing] = useState(false);

  const [editingCategory, setEditingCategory] = useState<Partial<CuisineCategory> | null>(null);
  const [isGeneratingCategoryImg, setIsGeneratingCategoryImg] = useState(false);

  const [editingDish, setEditingDish] = useState<Partial<Dish> | null>(null);
  const [lastImage, setLastImage] = useState<string | null>(null);
  const [isEnhancing, setIsEnhancing] = useState(false);

  const [suggestedDesc, setSuggestedDesc] = useState<string | null>(null);
  const [isGeneratingDesc, setIsGeneratingDesc] = useState(false);

  const [dragOverCategoryId, setDragOverCategoryId] = useState<string | null>(null);

  const generateId = () => {
    try {
        return crypto.randomUUID();
    } catch (e) {
        return Math.random().toString(36).substring(2) + Date.now().toString(36);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (base64: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => callback(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleLogOut = async () => {
    await signOut();
    onClose();
  };

  const saveCategory = async () => {
    if (!editingCategory?.name || !editingCategory.image) return;
    setIsSyncing(true);
    try {
        const catToSave: CuisineCategory = {
            id: editingCategory.id || generateId(),
            name: editingCategory.name,
            description: editingCategory.description || '',
            image: editingCategory.image,
            isHidden: editingCategory.isHidden || false
        };
        await upsertCategory(catToSave);
        if (editingCategory.id) {
          setCategories(prev => prev.map(c => c.id === catToSave.id ? catToSave : c));
        } else {
          setCategories(prev => [...prev, catToSave].sort((a, b) => a.name.localeCompare(b.name)));
        }
        setEditingCategory(null);
    } catch (e) {
        console.error("Failed to save category:", e);
        alert("Persistence error.");
    } finally {
        setIsSyncing(false);
    }
  };

  const removeCategory = async (id: string) => {
    if (!confirm("Are you sure? All dishes in this category will be orphaned.")) return;
    setIsSyncing(true);
    try {
        await deleteCategoryFromDB(id);
        setCategories(prev => prev.filter(c => c.id !== id));
    } catch (e) {
        console.error(e);
    } finally {
        setIsSyncing(false);
    }
  }

  const handleGenerateCategoryImage = async () => {
      if (!editingCategory?.name) return;
      setIsGeneratingCategoryImg(true);
      try {
          const prompt = `A professional food photography image representing the cuisine category: ${editingCategory.name}. ${editingCategory.description ? `Description: ${editingCategory.description}` : ''}. High quality, appetizing, photorealistic, premium lighting.`;
          const image = await generateImageFromText(prompt);
          if (image) {
              setEditingCategory(prev => ({ ...prev, image }));
          } else {
              alert("Failed to generate image.");
          }
      } catch (e) {
          console.error(e);
      } finally {
          setIsGeneratingCategoryImg(false);
      }
  };

  const renderCategoryEditor = () => (
    <div className="bg-white/90 dark:bg-zinc-900/90 backdrop-blur-2xl p-8 rounded-2xl shadow-2xl max-w-2xl mx-auto border border-white/50 dark:border-white/5 animate-scale-in no-scrollbar max-h-[90vh] overflow-y-auto">
        <h3 className="text-2xl font-bold mb-6 text-gray-800 dark:text-gray-100">{editingCategory?.id ? 'Edit Category' : 'New Category'}</h3>
        <div className="space-y-6">
            <div>
                <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Name</label>
                <input 
                    type="text" 
                    className="w-full bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 p-3 rounded-lg focus:ring-2 focus:ring-black/10 dark:focus:ring-white/10 focus:outline-none transition-all dark:text-white" 
                    value={editingCategory?.name || ''} 
                    onChange={e => setEditingCategory(p => ({...p, name: e.target.value}))}
                />
            </div>
            <div>
                <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Description</label>
                <textarea 
                    className="w-full bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 p-3 rounded-lg focus:ring-2 focus:ring-black/10 dark:focus:ring-white/10 focus:outline-none transition-all dark:text-white h-24" 
                    value={editingCategory?.description || ''} 
                    onChange={e => setEditingCategory(p => ({...p, description: e.target.value}))}
                />
            </div>
            <div>
                <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Card Image</label>
                <div className="flex flex-col gap-3">
                    {editingCategory?.image ? (
                        <div className="responsive-image bg-gray-50 rounded-xl overflow-hidden relative">
                            <img src={editingCategory.image} alt={editingCategory.name} />
                            <button onClick={() => setEditingCategory(p => ({...p, image: undefined}))} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow hover:bg-red-600 transition-opacity z-10"><X size={12}/></button>
                        </div>
                    ) : (
                        <div className="w-full aspect-video bg-gray-100 dark:bg-white/5 rounded-xl flex items-center justify-center text-gray-400 border-2 border-dashed border-gray-200 dark:border-white/10">
                            <ImageIcon size={32} />
                        </div>
                    )}
                    <div className="flex gap-2">
                        <label className="flex-1 cursor-pointer bg-black dark:bg-white text-white dark:text-black px-4 py-2 rounded-lg hover:bg-gray-800 dark:hover:bg-gray-200 transition-colors flex items-center justify-center gap-2 text-xs font-bold uppercase tracking-wider shadow-md">
                            <Upload size={14} /> Upload
                            <input type="file" className="hidden" accept="image/*" onChange={(e) => handleFileUpload(e, (base64) => setEditingCategory(p => ({...p, image: base64})))} />
                        </label>
                        <button onClick={handleGenerateCategoryImage} disabled={!editingCategory?.name || isGeneratingCategoryImg} className="flex-1 bg-purple-600 text-white px-4 py-2 rounded-lg hover:bg-purple-700 transition-colors flex items-center justify-center gap-2 text-xs font-bold uppercase tracking-wider disabled:opacity-50 shadow-md">
                            {isGeneratingCategoryImg ? <Loader2 className="animate-spin" size={14} /> : <Wand2 size={14} />} AI
                        </button>
                    </div>
                </div>
            </div>
        </div>

        <div className="flex justify-end gap-3 mt-8 pt-6 border-t border-gray-100 dark:border-white/10">
            <button onClick={() => setEditingCategory(null)} className="px-6 py-3 text-gray-500 hover:bg-gray-100 dark:hover:bg-white/10 rounded-xl transition-colors">Cancel</button>
            <button onClick={saveCategory} disabled={isSyncing} className="px-8 py-3 bg-black dark:bg-white text-white dark:text-black rounded-xl shadow-lg hover:shadow-xl hover:scale-105 transition-all font-medium flex items-center gap-2">
                {isSyncing && <Loader2 size={16} className="animate-spin" />}
                Save Category
            </button>
        </div>
    </div>
  );

  const saveDish = async () => {
    if (!editingDish?.name || !editingDish.categoryId || !editingDish.image || !editingDish.nutrition) return;

    const dishToSave = {
        ...editingDish,
        id: editingDish.id || generateId(),
        description: editingDish.description || '',
        sideDishes: editingDish.sideDishes || [],
        ingredients: editingDish.ingredients || [],
        suitableFor: editingDish.suitableFor || [],
        isHidden: editingDish.isHidden || false
    } as Dish;

    setIsSyncing(true);
    try {
        await upsertDish(dishToSave);
        if (editingDish.id) {
          setDishes(prev => prev.map(d => d.id === dishToSave.id ? dishToSave : d));
        } else {
          setDishes(prev => [...prev, dishToSave]);
        }
        setEditingDish(null);
        setSuggestedDesc(null);
        setLastImage(null);
    } catch (e) {
        console.error("Failed to save dish:", e);
        alert("Database error.");
    } finally {
        setIsSyncing(false);
    }
  };

  const removeDish = async (id: string) => {
    setIsSyncing(true);
    try {
        await deleteDishFromDB(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        if (promotedDishId === id) setPromotedDishId(null);
    } catch (e) {
        console.error(e);
    } finally {
        setIsSyncing(false);
    }
  }

  const handleAIImageEnhance = async (type: 'lighting' | 'color' | 'remove-bg' | 'replace-bg' | 'upscale' | 'zoom-in' | 'zoom-out', modifier?: string) => {
    if (!editingDish?.image) return;
    setLastImage(editingDish.image); 
    setIsEnhancing(true);
    try {
      const enhanced = await enhanceDishImage(editingDish.image, type, modifier);
      if (enhanced) {
        setEditingDish(prev => ({ ...prev, image: enhanced }));
      }
    } catch (e) { console.error(e); } finally { setIsEnhancing(false); }
  };

  /**
   * Fix: Added handleGenerateDescription to trigger Gemini API for creative writing.
   */
  const handleGenerateDescription = async () => {
    if (!editingDish?.name || !editingDish.ingredients) return;
    setIsGeneratingDesc(true);
    try {
      const desc = await suggestDishDescription(editingDish.name, editingDish.ingredients);
      setSuggestedDesc(desc);
    } catch (e) {
      console.error("Description generation failed:", e);
    } finally {
      setIsGeneratingDesc(false);
    }
  };

  /**
   * Fix: Added renderDishEditor to provide the missing UI component for managing dish details.
   */
  const renderDishEditor = () => (
    <div className="bg-white/90 dark:bg-zinc-900/90 backdrop-blur-2xl p-8 rounded-2xl shadow-2xl max-w-4xl mx-auto border border-white/50 dark:border-white/5 animate-scale-in no-scrollbar max-h-[90vh] overflow-y-auto">
        <div className="flex justify-between items-center mb-6">
            <h3 className="text-2xl font-bold text-gray-800 dark:text-gray-100">{editingDish?.id ? 'Edit Dish' : 'New Dish'}</h3>
            <div className="flex gap-2">
                {lastImage && (
                    <button onClick={() => setEditingDish(p => ({...p, image: lastImage}))} className="p-2 text-gray-400 hover:text-black dark:hover:text-white transition-colors" title="Undo Last Enhance">
                        <Undo2 size={20} />
                    </button>
                )}
            </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
            {/* Left Column: Media & AI */}
            <div className="space-y-6">
                <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Presentation Image</label>
                    <div className="group relative rounded-2xl overflow-hidden bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 aspect-[4/3] flex items-center justify-center">
                        {editingDish?.image ? (
                            <>
                                <img src={editingDish.image} alt="Preview" className="w-full h-full object-cover" />
                                {isEnhancing && (
                                    <div className="absolute inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-10">
                                        <div className="flex flex-col items-center gap-2">
                                            <Loader2 className="animate-spin text-white" size={32} />
                                            <span className="text-white text-[10px] font-black uppercase tracking-widest">AI Enhancing...</span>
                                        </div>
                                    </div>
                                )}
                            </>
                        ) : (
                            <ImageIcon size={48} className="text-gray-300" />
                        )}
                    </div>
                    <div className="flex flex-wrap gap-2 mt-4">
                        <label className="flex-1 cursor-pointer bg-black dark:bg-white text-white dark:text-black px-4 py-3 rounded-xl hover:bg-gray-800 dark:hover:bg-gray-200 transition-all flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-wider shadow-md">
                            <Upload size={14} /> Upload
                            <input type="file" className="hidden" accept="image/*" onChange={(e) => handleFileUpload(e, (base64) => setEditingDish(p => ({...p, image: base64})))} />
                        </label>
                    </div>

                    <div className="mt-6 p-4 bg-purple-50 dark:bg-purple-900/20 rounded-2xl border border-purple-100 dark:border-purple-900/30">
                        <div className="flex items-center gap-2 mb-3">
                            <Sparkles size={14} className="text-purple-600 dark:text-purple-400" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-purple-600 dark:text-purple-400">AI Enhancement Suite</span>
                        </div>
                        <div className="grid grid-cols-2 gap-2">
                            <button onClick={() => handleAIImageEnhance('lighting')} disabled={!editingDish?.image || isEnhancing} className="flex items-center gap-2 p-2.5 bg-white dark:bg-black/40 rounded-lg text-[9px] font-bold uppercase tracking-wider hover:bg-purple-600 hover:text-white transition-all disabled:opacity-50"><Sun size={12}/> Lighting</button>
                            <button onClick={() => handleAIImageEnhance('color')} disabled={!editingDish?.image || isEnhancing} className="flex items-center gap-2 p-2.5 bg-white dark:bg-black/40 rounded-lg text-[9px] font-bold uppercase tracking-wider hover:bg-purple-600 hover:text-white transition-all disabled:opacity-50"><Palette size={12}/> Color</button>
                            <button onClick={() => handleAIImageEnhance('remove-bg')} disabled={!editingDish?.image || isEnhancing} className="flex items-center gap-2 p-2.5 bg-white dark:bg-black/40 rounded-lg text-[9px] font-bold uppercase tracking-wider hover:bg-purple-600 hover:text-white transition-all disabled:opacity-50"><Maximize size={12}/> Clear BG</button>
                            <button onClick={() => handleAIImageEnhance('zoom-out')} disabled={!editingDish?.image || isEnhancing} className="flex items-center gap-2 p-2.5 bg-white dark:bg-black/40 rounded-lg text-[9px] font-bold uppercase tracking-wider hover:bg-purple-600 hover:text-white transition-all disabled:opacity-50"><ZoomOut size={12}/> Zoom Out</button>
                        </div>
                    </div>
                </div>

                <div>
                    <div className="flex justify-between items-center mb-2">
                        <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Appetizing Description</label>
                        <button onClick={handleGenerateDescription} disabled={!editingDish?.name || isGeneratingDesc} className="flex items-center gap-1.5 text-purple-600 hover:text-purple-700 disabled:opacity-50 transition-colors">
                            {isGeneratingDesc ? <Loader2 className="animate-spin" size={12} /> : <Wand2 size={12} />}
                            <span className="text-[10px] font-black uppercase tracking-widest">Suggest</span>
                        </button>
                    </div>
                    <textarea 
                        className="w-full bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 p-4 rounded-xl focus:ring-2 focus:ring-black/10 dark:focus:ring-white/10 focus:outline-none transition-all dark:text-white h-28 text-sm leading-relaxed" 
                        value={editingDish?.description || ''} 
                        onChange={e => setEditingDish(p => ({...p, description: e.target.value}))}
                        placeholder="Describe this culinary creation..."
                    />
                    {suggestedDesc && (
                        <div className="mt-2 p-3 bg-purple-50 dark:bg-purple-900/10 rounded-lg border border-purple-100 dark:border-purple-800/20 text-xs italic text-purple-700 dark:text-purple-300 flex justify-between items-start gap-3">
                            <p>{suggestedDesc}</p>
                            <button onClick={() => {setEditingDish(p => ({...p, description: suggestedDesc})); setSuggestedDesc(null);}} className="p-1 bg-purple-600 text-white rounded hover:bg-purple-700 shrink-0"><Copy size={12}/></button>
                        </div>
                    )}
                </div>
            </div>

            {/* Right Column: Details & Stats */}
            <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Dish Name</label>
                        <input type="text" className="w-full bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 p-3 rounded-lg text-sm font-bold dark:text-white" value={editingDish?.name || ''} onChange={e => setEditingDish(p => ({...p, name: e.target.value}))} />
                    </div>
                    <div>
                        <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Category</label>
                        <select className="w-full bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 p-3 rounded-lg text-sm dark:text-white" value={editingDish?.categoryId || ''} onChange={e => setEditingDish(p => ({...p, categoryId: e.target.value}))}>
                            <option value="">Select Category</option>
                            {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                        </select>
                    </div>
                </div>

                <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Nutritional Values</label>
                    <div className="grid grid-cols-5 gap-2">
                        {[
                            { label: 'Cals', key: 'calories', icon: Flame },
                            { label: 'Prot', key: 'protein', icon: Beef },
                            { label: 'Fat', key: 'fat', icon: Droplets },
                            { label: 'Carb', key: 'carbohydrates', icon: Wheat },
                            { label: 'Fiber', key: 'fiber', icon: Feather },
                        ].map((stat) => (
                            <div key={stat.key} className="bg-white/50 dark:bg-white/5 border border-gray-100 dark:border-white/10 p-2.5 rounded-xl flex flex-col items-center">
                                <stat.icon size={12} className="text-gray-300 mb-1" />
                                <span className="text-[8px] font-black uppercase text-gray-400 mb-1">{stat.label}</span>
                                <input 
                                    type="number" 
                                    className="w-full bg-transparent text-center text-xs font-black dark:text-white outline-none" 
                                    value={editingDish?.nutrition?.[stat.key as keyof typeof editingDish.nutrition] || 0} 
                                    onChange={e => setEditingDish(p => ({...p, nutrition: {...p.nutrition!, [stat.key]: parseFloat(e.target.value) || 0}}))}
                                />
                            </div>
                        ))}
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Ingredients</label>
                        <textarea 
                            className="w-full bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 p-3 rounded-lg text-xs h-24 dark:text-white" 
                            placeholder="Comma separated ingredients..."
                            value={editingDish?.ingredients?.join(', ') || ''} 
                            onChange={e => setEditingDish(p => ({...p, ingredients: e.target.value.split(',').map(s => s.trim()).filter(Boolean)}))}
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Side Dishes</label>
                        <textarea 
                            className="w-full bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 p-3 rounded-lg text-xs h-24 dark:text-white" 
                            placeholder="Comma separated sides..."
                            value={editingDish?.sideDishes?.join(', ') || ''} 
                            onChange={e => setEditingDish(p => ({...p, sideDishes: e.target.value.split(',').map(s => s.trim()).filter(Boolean)}))}
                        />
                    </div>
                </div>

                <div>
                   <label className="flex items-center gap-2 cursor-pointer group">
                       <input type="checkbox" className="w-4 h-4 rounded border-gray-300 text-black focus:ring-black" checked={editingDish?.isHidden || false} onChange={e => setEditingDish(p => ({...p, isHidden: e.target.checked}))} />
                       <span className="text-xs font-bold uppercase tracking-widest text-gray-500 group-hover:text-black dark:group-hover:text-white transition-colors">Hide from Menu</span>
                   </label>
                </div>
            </div>
        </div>

        <div className="flex justify-between items-center mt-10 pt-8 border-t border-gray-100 dark:border-white/10">
            <button onClick={() => { setEditingDish(null); setSuggestedDesc(null); }} className="px-6 py-3 text-gray-500 hover:bg-gray-100 dark:hover:bg-white/10 rounded-xl transition-colors font-medium">Cancel</button>
            <div className="flex gap-3">
                {editingDish?.id && (
                    <button onClick={() => setPromotedDishId(editingDish.id!)} className={`px-6 py-3 rounded-xl font-bold flex items-center gap-2 transition-all ${promotedDishId === editingDish.id ? 'bg-amber-100 text-amber-600' : 'bg-gray-100 text-gray-500 hover:bg-amber-500 hover:text-white'}`}>
                        <Star size={16} fill={promotedDishId === editingDish.id ? "currentColor" : "none"} />
                        {promotedDishId === editingDish.id ? 'Promoted' : 'Promote'}
                    </button>
                )}
                <button onClick={saveDish} disabled={isSyncing} className="px-10 py-3 bg-black dark:bg-white text-white dark:text-black rounded-xl shadow-lg hover:shadow-xl hover:scale-105 transition-all font-bold flex items-center gap-2">
                    {isSyncing && <Loader2 size={16} className="animate-spin" />}
                    {editingDish?.id ? 'Update Dish' : 'Create Dish'}
                </button>
            </div>
        </div>
    </div>
  );

  const handleDragStart = (e: React.DragEvent, dishId: string) => { e.dataTransfer.setData('dishId', dishId); e.dataTransfer.effectAllowed = 'move'; };
  const handleDragOver = (e: React.DragEvent, categoryId: string) => { e.preventDefault(); setDragOverCategoryId(categoryId); };
  const handleDrop = async (e: React.DragEvent, categoryId: string) => {
      e.preventDefault();
      const dishId = e.dataTransfer.getData('dishId');
      if (dishId) {
          const dish = dishes.find(d => d.id === dishId);
          if (dish) {
              const updated = { ...dish, categoryId };
              setIsSyncing(true);
              try { await upsertDish(updated); setDishes(prev => prev.map(d => d.id === dishId ? updated : d)); } catch (e) { console.error(e); } finally { setIsSyncing(false); }
          }
      }
      setDragOverCategoryId(null);
  };

  return (
    <div className="fixed inset-0 bg-black/5 dark:bg-black/40 z-50 overflow-y-auto backdrop-blur-sm animate-fade-in">
        <div className="bg-white/80 dark:bg-zinc-950/80 backdrop-blur-md border-b border-white/20 dark:border-white/5 px-10 py-6 flex justify-between items-center sticky top-0 z-20 shadow-sm">
            <div className="flex items-center gap-3">
                 <div className={`w-3 h-3 rounded-full ${isSyncing ? 'bg-amber-500 animate-pulse' : 'bg-green-500'}`}></div>
                 <h1 className="text-xl font-bold tracking-tight dark:text-white">Chef Dashboard</h1>
            </div>
            <div className="flex items-center gap-4">
              <button onClick={handleLogOut} className="flex items-center gap-2 px-4 py-2 text-sm font-bold text-gray-500 hover:text-red-600 transition-colors"><LogOut size={18} /> Log Out</button>
              <button onClick={onClose} className="p-2 bg-gray-100 dark:bg-white/5 rounded-full hover:bg-gray-200 dark:hover:bg-white/10 transition-colors dark:text-white"><X size={20}/></button>
            </div>
        </div>

        <div className="max-w-7xl mx-auto p-10">
            {editingCategory ? renderCategoryEditor() : editingDish ? renderDishEditor() : (
                <>
                    <div className="flex gap-8 mb-10 border-b border-gray-200 dark:border-white/10">
                        <button className={`pb-4 px-2 text-lg transition-all ${activeTab === 'categories' ? 'border-b-2 border-black dark:border-white font-bold dark:text-white' : 'text-gray-400 hover:text-gray-600'}`} onClick={() => setActiveTab('categories')}>Categories</button>
                        <button className={`pb-4 px-2 text-lg transition-all ${activeTab === 'dishes' ? 'border-b-2 border-black dark:border-white font-bold dark:text-white' : 'text-gray-400 hover:text-gray-600'}`} onClick={() => setActiveTab('dishes')}>Dishes</button>
                    </div>

                    {activeTab === 'categories' ? (
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                            <button onClick={() => setEditingCategory({})} className="h-64 border-2 border-dashed border-gray-300 dark:border-white/10 rounded-2xl flex flex-col items-center justify-center text-gray-400 hover:border-black dark:hover:border-white hover:text-black dark:hover:text-white hover:bg-gray-50 dark:hover:bg-white/5 transition-all group">
                                <div className="p-4 bg-gray-100 dark:bg-white/5 rounded-full mb-4 group-hover:scale-110 transition-transform"><Plus size={32} /></div>
                                <span className="font-medium">New Category</span>
                            </button>
                            {categories.map((cat, i) => (
                                <div key={cat.id} className={`bg-white dark:bg-zinc-900 rounded-2xl shadow-sm hover:shadow-xl transition-all duration-300 overflow-hidden group relative animate-slide-up ${cat.isHidden ? 'opacity-75' : ''}`} style={{animationDelay: `${i*100}ms`}}>
                                    <div className="responsive-image bg-gray-50">
                                        <img src={cat.image} alt={cat.name} className={`transform group-hover:scale-110 transition-transform duration-700 ${cat.isHidden ? 'grayscale' : ''}`} />
                                    </div>
                                    <div className="p-6">
                                        <h4 className="font-bold text-xl mb-2 flex items-center gap-2 dark:text-white">{cat.name}</h4>
                                        <p className="text-sm text-gray-500 dark:text-zinc-400 line-clamp-2 leading-relaxed">{cat.description}</p>
                                    </div>
                                    <div className="absolute top-3 right-3 flex gap-2 opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0 z-10">
                                        <button onClick={() => setEditingCategory(cat)} className="p-2.5 bg-white/95 dark:bg-black/80 backdrop-blur-md rounded-full shadow-lg hover:bg-black dark:hover:bg-white hover:text-white dark:hover:text-black transition-all hover:scale-110 border border-black/5 dark:border-white/10"><Edit size={16}/></button>
                                        <button onClick={() => removeCategory(cat.id)} className="p-2.5 bg-white/95 dark:bg-black/80 backdrop-blur-md text-red-600 rounded-full shadow-lg hover:bg-red-500 hover:text-white transition-all hover:scale-110 border border-black/5 dark:border-white/10"><Trash2 size={16}/></button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="space-y-10">
                            <button onClick={() => setEditingDish({ nutrition: { calories: 0, protein: 0, fat: 0, carbohydrates: 0, fiber: 0 } })} className="flex items-center gap-2 bg-black dark:bg-white text-white dark:text-black px-6 py-3 rounded-xl shadow-lg hover:scale-105 transition-all font-bold"><Plus size={18}/> Add New Dish</button>
                            {categories.map(cat => (
                                <div key={cat.id} className={`bg-white/50 dark:bg-zinc-900/50 backdrop-blur-sm p-6 rounded-3xl border transition-all duration-300 ${dragOverCategoryId === cat.id ? 'border-blue-400 bg-blue-50/50' : 'border-gray-200 dark:border-white/5'}`} onDragOver={(e) => handleDragOver(e, cat.id)} onDrop={(e) => handleDrop(e, cat.id)}>
                                    <h3 className="text-xl font-bold mb-6 dark:text-white flex items-center gap-3"><div className="w-1.5 h-6 bg-black dark:bg-white rounded-full"></div>{cat.name}</h3>
                                    <div className="grid grid-cols-1 md:grid-cols-4 gap-6 min-h-[100px]">
                                        {dishes.filter(d => d.categoryId === cat.id).map((dish) => (
                                            <div key={dish.id} className="bg-white dark:bg-zinc-800 rounded-2xl p-3 gap-3 shadow-sm hover:shadow-md transition-all group relative border border-transparent hover:border-gray-100 dark:hover:border-white/10" draggable onDragStart={(e) => handleDragStart(e, dish.id)}>
                                                <div className="flex items-center gap-4">
                                                    <div className="w-16 h-16 rounded-xl overflow-hidden bg-gray-50 flex-shrink-0"><img src={dish.image} className="w-full h-full object-contain" alt={dish.name} /></div>
                                                    <div className="flex-1 min-w-0"><div className="font-bold truncate text-gray-800 dark:text-zinc-100">{dish.name}</div><div className="text-[10px] text-orange-500 font-mono font-bold mt-1 uppercase tracking-wider">{dish.nutrition.calories} kcal</div></div>
                                                </div>
                                                <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-all flex gap-1 z-10">
                                                    <button onClick={() => setEditingDish(dish)} className="p-1.5 bg-white dark:bg-black rounded-full shadow-lg border dark:border-white/10"><Edit size={14}/></button>
                                                    <button onClick={() => removeDish(dish.id)} className="p-1.5 bg-white dark:bg-black text-red-500 rounded-full shadow-lg border dark:border-white/10"><Trash2 size={14}/></button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </>
            )}
        </div>
    </div>
  );
};

{
  "name": "MADYAF Menu App",
