}

import React, { useState, useEffect } from 'react';
import { AppState, CuisineCategory, Dish, ThemeType } from './types';
import { ThemeWrapper } from './components/ThemeWrapper';
import { AdminPanel } from './components/AdminPanel';
import { ClientView, PDFExportView } from './components/ClientView';
import { AuthForm } from './components/AuthForm';
import { Settings, ChefHat, Palette, FileText, X, ArrowRight, Sun, Moon, Star, Image as ImageIcon, Upload } from 'lucide-react';
import { fetchCategories, fetchDishes, supabase } from './services/supabaseService';
import { User } from '@supabase/supabase-js';

const App: React.FC = () => {
  const [categories, setCategories] = useState<CuisineCategory[]>([]);
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [showAuth, setShowAuth] = useState(false);

  const [viewState, setViewState] = useState<AppState['view']>('menu-overview');
  const [currentCategory, setCurrentCategory] = useState<string | null>(null);
  const [currentDishIndex, setCurrentDishIndex] = useState(0);
  const [theme, setTheme] = useState<ThemeType>('modern');

  const [appTitle, setAppTitle] = useState("MADYAF");
  const [appSubtitle, setAppSubtitle] = useState("Private Dining Curations");
  const [appLogo, setAppLogo] = useState<string | null>(null);
  const [promotionTitle, setPromotionTitle] = useState("Signature Feature");
  const [philosophyTitle, setPhilosophyTitle] = useState("Nutritional Philosophy");
  const [philosophyDescription, setPhilosophyDescription] = useState("Every plate is balanced. Every calorie is considered. We believe private dining should be as nourishing as it is exquisite.");
  const [promotedDishId, setPromotedDishId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Auth State Listener
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
    });

    return () => subscription.unsubscribe();
  }, []);

  // Initial Data Fetch
  useEffect(() => {
    const loadData = async () => {
      try {
        const [cats, ds] = await Promise.all([fetchCategories(), fetchDishes()]);
        setCategories(cats);
        setDishes(ds);
        // Default promoted dish if none set
        if (ds.length > 0 && !promotedDishId) {
            setPromotedDishId(ds[0].id);
        }
        setDbError(null);
      } catch (err: any) {
        console.error("Supabase load error:", err);
        if (err.code === 'PGRST205' || err.message?.includes('not found')) {
          setDbError('DATABASE_SETUP_REQUIRED');
        } else {
          setDbError(err.message || 'Unknown database error');
        }
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  const handleAdminAccess = () => {
    if (user) {
      setViewState('admin');
      setIsSettingsOpen(false);
    } else {
      setShowAuth(true);
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setAppLogo(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const toggleSettings = () => {
    setIsSettingsOpen(!isSettingsOpen);
  };

  const visibleCategories = categories.filter(c => !c.isHidden);
  const visibleDishes = dishes.filter(d => 
    !d.isHidden && visibleCategories.some(c => c.id === d.categoryId)
  );

  const safeCurrentDishIndex = (currentDishIndex >= visibleDishes.length) ? 0 : currentDishIndex;

  const clientViewState = {
      view: viewState === 'menu-overview' || viewState === 'dish-viewer' ? viewState : 'menu-overview',
      currentCategory,
      currentDishIndex: safeCurrentDishIndex
  };

  const setClientViewState = (newState: any) => {
     if (typeof newState === 'function') {
         const res = newState(clientViewState);
         setViewState(res.view);
         setCurrentCategory(res.currentCategory);
         setCurrentDishIndex(res.currentDishIndex);
     } else {
         setViewState(newState.view);
         setCurrentCategory(newState.currentCategory);
         setCurrentDishIndex(newState.currentDishIndex);
     }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-white dark:bg-zinc-950 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-black/10 dark:border-white/10 border-t-black dark:border-t-white rounded-full animate-spin"></div>
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-400">Opening Kitchen</span>
        </div>
      </div>
    );
  }

  return (
    <ThemeWrapper theme={theme}>
        {showAuth && (
          <AuthForm 
            onSuccess={() => { setShowAuth(false); setViewState('admin'); setIsSettingsOpen(false); }}
            onCancel={() => setShowAuth(false)}
          />
        )}

        {(viewState === 'menu-overview' || viewState === 'dish-viewer') && (
            <div className="fixed top-6 right-6 z-[60] print:hidden">
                <button
                    onClick={toggleSettings}
                    className={`p-4 rounded-full shadow-2xl hover:scale-110 transition-all flex items-center justify-center ${isSettingsOpen ? 'bg-black text-white dark:bg-white dark:text-black' : 'bg-white text-black dark:bg-zinc-800 dark:text-white'}`}
                >
                    {isSettingsOpen ? <X size={24} /> : <Settings size={24} />}
                </button>
            </div>
        )}

        {isSettingsOpen && (
            <div className="fixed top-24 right-6 z-[70] w-96 bg-white/95 dark:bg-zinc-900/95 backdrop-blur-2xl p-8 rounded-[2rem] shadow-[0_20px_60px_-10px_rgba(0,0,0,0.3)] border border-white/50 dark:border-white/5 animate-scale-in origin-top-right print:hidden max-h-[85vh] overflow-y-auto no-scrollbar">
                <div className="space-y-8">
                    <div>
                        <div className="flex items-center gap-3 mb-6">
                            <Palette size={20} className="text-gray-800 dark:text-zinc-200"/>
                            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-gray-800 dark:text-zinc-200">Visual Identity</h3>
                        </div>

                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Logo</label>
                                <div className="flex items-center gap-4">
                                    <div className="w-16 h-16 bg-gray-50 dark:bg-white/5 rounded-xl flex items-center justify-center border border-gray-100 dark:border-white/10 overflow-hidden">
                                        {appLogo ? <img src={appLogo} className="w-full h-full object-contain" /> : <ImageIcon className="text-gray-300" />}
                                    </div>
                                    <label className="flex-1 cursor-pointer bg-black dark:bg-white text-white dark:text-black px-4 py-2 rounded-lg text-[10px] font-black uppercase text-center hover:opacity-80 transition-opacity">
                                        Upload Logo
                                        <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                                    </label>
                                </div>
                            </div>
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Restaurant Name</label>
                                <input 
                                    type="text" 
                                    value={appTitle} 
                                    onChange={e => setAppTitle(e.target.value)}
                                    className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl text-sm font-bold focus:ring-2 focus:ring-black/10 dark:focus:ring-white/10 outline-none dark:text-white"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] uppercase font-bold text-gray-400 block mb-1.5 ml-1">Tagline</label>
                                <input 
                                    type="text" 
                                    value={appSubtitle} 
                                    onChange={e => setAppSubtitle(e.target.value)}
                                    className="w-full bg-gray-50 dark:bg-white/5 border-none p-4 rounded-xl text-sm font-medium focus:ring-2 focus:ring-black/10 dark:focus:ring-white/10 outline-none dark:text-white"
                                />
                            </div>
                        </div>
                    </div>

                    <div>
                        <label className="text-[10px] uppercase font-bold text-gray-400 block mb-4 ml-1">Select Theme</label>
                        <div className="grid grid-cols-3 gap-3">
                            {[
                              { id: 'modern', name: 'Modern', icon: <Sun size={14}/> },
                              { id: 'classic', name: 'Classic', icon: <FileText size={14}/> },
                              { id: 'dark', name: 'Dark', icon: <Moon size={14}/> }
                            ].map(t => (
                                <button
                                    key={t.id}
                                    onClick={() => setTheme(t.id as ThemeType)}
                                    className={`flex flex-col items-center gap-2 px-3 py-4 rounded-2xl text-[10px] font-bold transition-all border-2 text-center leading-tight ${theme === t.id ? 'bg-black text-white border-black dark:bg-white dark:text-black dark:border-white scale-105 shadow-xl' : 'bg-gray-50 text-gray-400 border-transparent hover:border-gray-200 dark:bg-white/5 dark:hover:border-white/10'}`}
                                >
                                    {t.icon}
                                    {t.name}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-3">
                        <button onClick={handleAdminAccess} className="w-full flex items-center justify-between p-4 rounded-xl bg-gray-50 dark:bg-white/5 hover:bg-gray-100 dark:hover:bg-white/10 transition-colors text-sm font-bold text-gray-800 dark:text-zinc-200">
                            <div className="flex items-center gap-3">
                                <ChefHat size={20} className="text-black dark:text-white"/>
                                {user ? 'Chef Dashboard' : 'Chef Entrance'}
                            </div>
                            <ArrowRight size={16}/>
                        </button>
                    </div>
                </div>
            </div>
        )}

        {viewState === 'admin' ? (
            <AdminPanel 
                categories={categories} setCategories={setCategories}
                dishes={dishes} setDishes={setDishes}
                promotedDishId={promotedDishId}
                setPromotedDishId={setPromotedDishId}
                onClose={() => setViewState('menu-overview')}
            />
        ) : viewState === 'pdf-preview' ? (
            <PDFExportView dishes={visibleDishes} categories={visibleCategories} theme={theme} onClose={() => setViewState('menu-overview')} />
        ) : (
            <ClientView 
                categories={visibleCategories}
                dishes={visibleDishes}
                viewState={clientViewState as any}
                setViewState={setClientViewState}
                theme={theme}
                appTitle={appTitle}
                appSubtitle={appSubtitle}
                appLogo={appLogo}
                promotionTitle={promotionTitle}
                philosophyTitle={philosophyTitle}
                philosophyDescription={philosophyDescription}
                promotedDishId={promotedDishId}
            />
        )}
    </ThemeWrapper>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { CuisineCategory, Dish, ThemeType, SuitableForTag } from '../types';
import { 
  ChevronLeft, Home, Settings, Flame, Beef, Coffee, 
  Sun, Moon, Zap, Activity, Feather, Wheat, Loader2, ArrowRight,
  Droplets, X, Maximize2, Clock, ChevronRight
} from 'lucide-react';

interface ClientViewProps {
  categories: CuisineCategory[];
  dishes: Dish[];
  viewState: {
    view: 'menu-overview' | 'dish-viewer';
    currentCategory: string | null;
    currentDishIndex: number;
  };
  setViewState: React.Dispatch<React.SetStateAction<any>>;
  theme: ThemeType;
  appTitle: string;
  appSubtitle: string;
  appLogo?: string | null;
  promotionTitle?: string;
  philosophyTitle?: string;
  philosophyDescription?: string;
  promotedDishId?: string | null;
  isOffline?: boolean;
  onOpenSettings?: () => void;
}

const Logo = ({ className = "w-10 h-10", logoUrl }: { className?: string, logoUrl?: string | null }) => {
  if (logoUrl) {
    return <img src={logoUrl} className={className} alt="MADYAF Logo" />;
  }
  // Simplified SVG recreation of the MADYAF brand mark
  return (
    <svg viewBox="0 0 100 100" className={className} fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="M10 50C10 27.9086 27.9086 10 50 10C72.0914 10 90 27.9086 90 50C90 72.0914 72.0914 90 50 90" stroke="#A68A64" strokeWidth="4" strokeLinecap="round"/>
      <path d="M50 20V24" stroke="#A68A64" strokeWidth="6" strokeLinecap="round"/>
      <path d="M30 45C30 36.7157 36.7157 30 45 30H55C63.2843 30 70 36.7157 70 45V48H30V45Z" fill="#A68A64"/>
      <path d="M25 50H75" stroke="#A68A64" strokeWidth="4" strokeLinecap="round"/>
      <circle cx="50" cy="20" r="3" fill="#A68A64"/>
    </svg>
  );
};

const ImageWithFallback = ({ src, alt, className }: { src: string; alt: string; className: string }) => {
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(true);

  return (
    <div className={`responsive-image bg-gray-50 dark:bg-zinc-800 ${className}`}>
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center z-10">
          <Loader2 className="animate-spin text-gray-300 dark:text-zinc-600" size={32} />
        </div>
      )}
      <img
        src={error ? 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&q=80&w=800' : src}
        alt={alt}
        className={`transition-all duration-1000 ${loading ? 'opacity-0 scale-110' : 'opacity-100 scale-100'}`}
        onLoad={() => setLoading(false)}
        onError={() => {
          setError(true);
          setLoading(false);
        }}
      />
    </div>
  );
};

const NutritionStat = ({ 
  label, 
  value, 
  unit = 'g', 
  isLast = false, 
  colorClass = "text-black dark:text-white",
  icon: Icon,
  animate = false
}: { 
  label: string, 
  value: number | string, 
  unit?: string, 
  isLast?: boolean, 
  colorClass?: string,
  icon?: React.ElementType,
  animate?: boolean
}) => (
  <div className={`flex-1 flex flex-col items-center px-1 ${!isLast ? 'border-r border-gray-100 dark:border-white/10' : ''}`}>
    <div className="flex items-center gap-1.5 mb-2 group">
      {Icon && <Icon size={12} className={`${animate ? 'text-orange-500' : 'text-gray-200 dark:text-zinc-700'} group-hover:text-gray-400 transition-colors`} />}
      <div className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-300 dark:text-zinc-600">{label}</div>
    </div>
    <div className={`text-2xl font-black leading-none tracking-tighter ${colorClass} ${animate ? 'animate-pulse' : ''}`}>
      {value}<span className="text-[10px] ml-0.5 opacity-40 font-bold lowercase tracking-normal">{unit}</span>
    </div>
  </div>
);

interface DishCardProps {
  dish: Dish;
  isClassic: boolean;
  onImageClick: (src: string) => void;
  index: number;
}

const DishCard: React.FC<DishCardProps> = ({ dish, isClassic, onImageClick, index }) => {
  const allComponents = [...dish.sideDishes, ...dish.ingredients];

  return (
    <div className="bg-white dark:bg-zinc-900 rounded-[3rem] overflow-hidden shadow-[0_40px_80px_-20px_rgba(0,0,0,0.06)] flex flex-col group hover:translate-y-[-8px] transition-all duration-500 h-full border border-gray-50 dark:border-white/5 opacity-0 animate-slide-up" style={{ animationFillMode: 'forwards' }}>
      <div 
        className="relative overflow-hidden cursor-zoom-in group/img bg-gray-100 dark:bg-zinc-800"
        onClick={() => onImageClick(dish.image)}
      >
        <div className="absolute top-8 left-8 z-20 w-12 h-12 flex items-center justify-center bg-gray-400/20 dark:bg-black/40 backdrop-blur-md text-gray-500 dark:text-zinc-300 text-xs font-black rounded-full border border-white/20 dark:border-white/10 shadow-sm transition-transform duration-500 select-none tracking-widest">
          {(index + 1).toString().padStart(2, '0')}
        </div>
        <ImageWithFallback src={dish.image} alt={dish.name} className="group-hover:scale-110 transition-transform duration-[3s] ease-out" />
      </div>

      <div className="p-12 flex-1 flex flex-col">
        <div className="mb-10">
          <h3 className={`text-5xl font-black tracking-tighter text-[#1A1A1A] dark:text-zinc-100 mb-8 leading-none ${isClassic ? 'font-serif italic' : ''}`}>
            {dish.name}
          </h3>
          <div className="flex flex-wrap items-center gap-2 mb-10">
            {allComponents.map((item, idx) => (
              <span 
                key={idx} 
                className="px-4 py-2.5 bg-gray-50/80 dark:bg-white/5 border border-gray-100/50 dark:border-white/5 rounded-full text-[9px] font-black uppercase tracking-[0.2em] text-gray-400 dark:text-zinc-500 whitespace-nowrap shadow-sm hover:bg-white dark:hover:bg-white/10 hover:shadow-md hover:border-gray-200 transition-all duration-300"
              >
                {item}
              </span>
            ))}
          </div>
          <p className="text-gray-400 dark:text-zinc-500 text-lg font-light leading-relaxed line-clamp-3 italic">
            {dish.description}
          </p>
        </div>
        <div className="mt-auto pt-10 border-t border-gray-50 dark:border-white/5">
          <div className="flex items-center justify-between">
            <NutritionStat label="Cals" value={dish.nutrition.calories} unit="" icon={Flame} colorClass="text-orange-500" animate={true} />
            <NutritionStat label="Prot" value={dish.nutrition.protein} icon={Beef} />
            <NutritionStat label="Fat" value={dish.nutrition.fat} icon={Droplets} />
            <NutritionStat label="Carb" value={dish.nutrition.carbohydrates} icon={Wheat} />
            <NutritionStat label="Fiber" value={dish.nutrition.fiber} isLast icon={Feather} />
          </div>
        </div>
      </div>
    </div>
  );
};

const Lightbox = ({ src, onClose }: { src: string; onClose: () => void }) => (
  <div 
    className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 cursor-zoom-out animate-fade-in p-6 md:p-20"
    onClick={onClose}
  >
    <button 
      className="absolute top-10 right-10 text-white/40 hover:text-white p-4 transition-all hover:rotate-90 duration-500"
      onClick={(e) => { e.stopPropagation(); onClose(); }}
    >
      <X size={40} />
    </button>
    <img 
      src={src} 
      className="max-w-full max-h-full object-contain rounded-3xl shadow-2xl border border-white/10 animate-scale-in select-none" 
      alt="Full size"
      onClick={(e) => e.stopPropagation()}
    />
  </div>
);

export const ClientView: React.FC<ClientViewProps> = ({ categories, dishes, viewState, setViewState, theme, appTitle, appSubtitle, appLogo, promotionTitle, philosophyTitle, philosophyDescription, promotedDishId }) => {
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);
  const [activeCategoryIndex, setActiveCategoryIndex] = useState(0);
  const isClassic = theme === 'classic';

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setZoomedImage(null);
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, []);

  const handleNextCategory = () => setActiveCategoryIndex((prev) => (prev + 1) % categories.length);
  const handlePrevCategory = () => setActiveCategoryIndex((prev) => (prev - 1 + categories.length) % categories.length);

  if (viewState.view === 'menu-overview') {
    const promotedDish = promotedDishId ? dishes.find(d => d.id === promotedDishId) : null;

    return (
      <div className="min-h-screen bg-[#FBFBFA] dark:bg-zinc-950 text-slate-900 dark:text-slate-100 selection:bg-slate-900 selection:text-white antialiased overflow-x-hidden">
        <div className="max-w-7xl mx-auto px-8 py-24 md:py-32">
          <header className="mb-24 flex flex-col md:flex-row md:items-start justify-between gap-12 opacity-0 animate-slide-up" style={{ animationFillMode: 'forwards' }}>
            <div className="relative transform-gpu flex flex-col items-start">
              <div className="flex items-center gap-6 mb-4">
                <Logo className="w-16 h-16 md:w-24 md:h-24" logoUrl={appLogo} />
                <h1 className="text-6xl md:text-8xl font-black tracking-tighter text-slate-900 dark:text-white leading-none uppercase">
                  {appTitle}
                </h1>
              </div>
              <div className="text-4xl md:text-6xl text-[#A68A64] dark:text-[#D1C2A4] italic font-['Playfair_Display'] font-normal leading-none ml-2 drop-shadow-sm">
                Selection
              </div>
            </div>
            <div className="md:mt-4 md:max-w-xs">
              <p className="text-slate-400 dark:text-zinc-500 text-xs md:text-sm font-black uppercase tracking-[0.5em] leading-relaxed">
                {appSubtitle}
              </p>
            </div>
          </header>

          <div className="relative mb-32 group">
            <div className="flex items-center justify-between mb-10">
              <span className="text-[10px] font-black uppercase tracking-[0.6em] text-gray-300 dark:text-zinc-700">Choose Your Menu Selection</span>
              <div className="flex gap-4">
                <button 
                  onClick={handlePrevCategory}
                  className="w-12 h-12 flex items-center justify-center rounded-full border border-gray-200 dark:border-white/10 hover:bg-black hover:text-white dark:hover:bg-white dark:hover:text-black transition-all"
                >
                  <ChevronLeft size={20} />
                </button>
                <button 
                  onClick={handleNextCategory}
                  className="w-12 h-12 flex items-center justify-center rounded-full border border-gray-200 dark:border-white/10 hover:bg-black hover:text-white dark:hover:bg-white dark:hover:text-black transition-all"
                >
                  <ChevronRight size={20} />
                </button>
              </div>
            </div>

            <div className="relative h-[600px] flex items-center overflow-visible">
              <div 
                className="flex gap-10 transition-transform duration-[1.2s] ease-[cubic-bezier(0.23,1,0.32,1)] items-center"
                style={{ transform: `translateX(-${activeCategoryIndex * (420 + 40)}px)` }}
              >
                {categories.map((category, idx) => {
                  const isActive = idx === activeCategoryIndex;
                  return (
                    <div 
                      key={category.id} 
                      className={`w-[420px] shrink-0 transition-all duration-1000 ${isActive ? 'scale-100 opacity-100 z-10' : 'scale-90 opacity-40 blur-[1px]'}`}
                      onClick={() => setActiveCategoryIndex(idx)}
                    >
                      <div 
                        onClick={() => isActive && setViewState({ view: 'dish-viewer', currentCategory: category.id, currentDishIndex: 0 })}
                        className={`group cursor-pointer relative rounded-[3.5rem] overflow-hidden bg-white dark:bg-zinc-900 border border-slate-100 dark:border-white/5 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.06)] transition-all duration-500 flex flex-col h-[550px] ${isActive ? 'hover:translate-y-[-8px] hover:shadow-[0_40px_80px_-20px_rgba(0,0,0,0.1)]' : ''}`}
                      >
                        <div className="w-full aspect-[4/3] overflow-hidden"><ImageWithFallback src={category.image} alt={category.name} className="group-hover:scale-110 transition-transform duration-[3s] ease-out" /></div>
                        <div className="p-12 flex flex-col justify-between flex-1 bg-white dark:bg-zinc-900">
                          <div>
                            <span className="text-[10px] font-black uppercase tracking-[0.6em] text-[#A68A64] mb-4 block">Discover The Collection</span>
                            <h2 className="text-4xl font-bold tracking-tight text-slate-900 dark:text-zinc-100 mb-6 group-hover:text-[#A68A64] transition-colors">{category.name}</h2>
                            <p className="text-xs text-gray-400 dark:text-zinc-500 font-light leading-relaxed line-clamp-3 italic">{category.description}</p>
                          </div>
                          <button className={`w-full py-5 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all duration-500 flex items-center justify-center gap-3 ${isActive ? 'bg-black dark:bg-white text-white dark:text-black translate-y-0 opacity-100' : 'bg-gray-100 text-gray-400 translate-y-4 opacity-0'}`}>Explore Menu <ArrowRight size={14} /></button>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="mt-12 flex justify-start gap-3 pl-2">
              {categories.map((_, i) => (
                <button key={i} onClick={() => setActiveCategoryIndex(i)} className={`h-1.5 rounded-full transition-all duration-500 ${i === activeCategoryIndex ? 'w-10 bg-[#A68A64]' : 'w-1.5 bg-gray-200 dark:bg-zinc-800 hover:bg-gray-400'}`} />
              ))}
            </div>
          </div>

          {promotedDish && (
            <section className="opacity-0 animate-slide-up" style={{ animationDelay: '400ms', animationFillMode: 'forwards' }}>
                <div className="flex items-center gap-6 mb-6">
                    <div className="h-px bg-gray-200 dark:bg-zinc-800 flex-1"></div>
                    <span className="text-[9px] font-black uppercase tracking-[1em] text-gray-400 px-4 leading-none">{promotionTitle || "Signature Feature"}</span>
                    <div className="h-px bg-gray-200 dark:bg-zinc-800 flex-1"></div>
                </div>
                <div className="relative group/promo">
                    <div className="bg-white dark:bg-zinc-900 rounded-[2rem] overflow-hidden flex flex-col lg:flex-row shadow-[0_30px_80px_-20px_rgba(0,0,0,0.08)] border border-gray-100/50 dark:border-white/5 transition-all duration-700">
                        <div className="lg:w-[40%] overflow-hidden bg-gray-50 dark:bg-black/20 relative">
                            <div className="aspect-[4/3] w-full cursor-zoom-in relative overflow-hidden group" onClick={() => setZoomedImage(promotedDish.image)}>
                                <img src={promotedDish.image} alt={promotedDish.name} className="w-full h-full object-cover transition-transform duration-[6s] group-hover:scale-105 ease-out" />
                                <div className="absolute inset-0 bg-gradient-to-t from-black/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
                            </div>
                        </div>
                        <div className="flex-1 p-6 lg:p-10 flex flex-col justify-center bg-white dark:bg-zinc-900 overflow-hidden">
                            <div className="flex items-center gap-3 mb-3"><span className="w-5 h-px bg-[#A68A64]"></span><span className="text-[8px] font-black uppercase tracking-[0.4em] text-[#A68A64]">Bespoke Choice</span></div>
                            <h2 className={`text-3xl lg:text-4xl font-black tracking-tighter text-slate-900 dark:text-zinc-100 mb-3 leading-tight ${isClassic ? 'font-serif italic' : ''}`}>{promotedDish.name}</h2>
                            <p className="text-sm lg:text-base text-slate-400 dark:text-zinc-500 font-light leading-relaxed mb-6 max-w-xl italic line-clamp-2">{promotedDish.description}</p>
                            <div className="pt-6 border-t border-gray-100 dark:border-white/5">
                                <div className="flex flex-col gap-3">
                                    <div className="flex items-center gap-2"><div className="p-1 bg-[#A68A64]/10 rounded"><Activity size={12} className="text-[#A68A64]" /></div><span className="text-[8px] font-black uppercase tracking-[0.2em] text-gray-300">Composition</span></div>
                                    <div className="grid grid-cols-5 gap-x-2">
                                        {[ { label: 'Cals', val: promotedDish.nutrition.calories, unit: '' }, { label: 'Prot', val: promotedDish.nutrition.protein, unit: 'g' }, { label: 'Fats', val: promotedDish.nutrition.fat, unit: 'g' }, { label: 'Carbs', val: promotedDish.nutrition.carbohydrates, unit: 'g' }, { label: 'Fiber', val: promotedDish.nutrition.fiber, unit: 'g' } ].map((stat, i) => (
                                            <div key={i} className="flex flex-col"><span className="text-[7px] font-black uppercase tracking-widest text-gray-300 dark:text-zinc-600 mb-0.5">{stat.label}</span><div className="flex items-baseline gap-0.5"><span className="text-lg font-black text-slate-800 dark:text-zinc-200 tracking-tighter">{stat.val}</span><span className="text-[7px] font-bold text-gray-300 uppercase">{stat.unit}</span></div></div>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </section>
          )}
        </div>
      </div>
    );
  }

  const currentCategoryDishes = dishes.filter(d => d.categoryId === viewState.currentCategory);
  const activeCategory = categories.find(c => c.id === viewState.currentCategory);

  return (
    <div 
      className="min-h-screen transition-all duration-700 ease-in-out font-['Inter'] selection:bg-black selection:text-white antialiased"
      style={{ backgroundColor: theme === 'dark' ? '#09090b' : '#FBFBFB' }}
    >
      {zoomedImage && <Lightbox src={zoomedImage} onClose={() => setZoomedImage(null)} />}

      <header className="px-12 py-10 flex justify-between items-center bg-white/90 dark:bg-black/80 backdrop-blur-md border-b border-gray-100 dark:border-white/5 sticky top-0 z-50">
        <div className="flex-1">
          <button 
            onClick={() => setViewState((p: any) => ({...p, view: 'menu-overview'}))} 
            className="flex items-center gap-5 group"
          >
            <div className="w-14 h-14 flex items-center justify-center bg-gray-50 dark:bg-white/5 rounded-full group-hover:bg-black dark:group-hover:bg-white group-hover:text-white dark:group-hover:text-black transition-all duration-500 shadow-sm border border-transparent dark:border-white/10">
              <Home size={22} />
            </div>
            <div className="hidden md:block text-left">
              <span className="text-[10px] font-black uppercase tracking-widest block text-gray-400 mb-0.5">Return to</span>
              <span className="text-sm font-bold tracking-tight dark:text-white">Main Selection</span>
            </div>
          </button>
        </div>

        <div className="text-center flex-1 flex flex-col items-center">
          <div className="flex items-center gap-3 mb-1">
            <Logo className="w-8 h-8" logoUrl={appLogo} />
            <h2 className={`text-xl font-black tracking-tight uppercase dark:text-white ${isClassic ? 'font-serif italic' : ''}`}>
              {activeCategory?.name || appTitle}
            </h2>
          </div>
          <div className="flex items-center justify-center gap-3">
            <div className="w-10 h-px bg-gray-200 dark:bg-white/10"></div>
            <span className="text-[10px] text-gray-400 dark:text-zinc-500 font-black uppercase tracking-[0.4em]">
              {currentCategoryDishes.length} Featured Creations
            </span>
            <div className="w-10 h-px bg-gray-200 dark:bg-white/10"></div>
          </div>
        </div>

        <div className="flex-1 flex justify-end"></div>
      </header>

      <main className="max-w-[1800px] mx-auto px-8 md:px-16 py-24">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-16 md:gap-24">
          {currentCategoryDishes.map((dish, idx) => (
            <DishCard 
              key={dish.id} 
              dish={dish} 
              isClassic={isClassic} 
              onImageClick={setZoomedImage}
              index={idx}
            />
          ))}
        </div>
      </main>
    </div>
  );
};

export const PDFExportView: React.FC<{ dishes: Dish[], categories: CuisineCategory[], theme: ThemeType, onClose: () => void }> = ({ dishes, categories, theme, onClose }) => {
    useEffect(() => {
        const timer = setTimeout(() => {
            window.print();
        }, 1200);
        return () => clearTimeout(timer);
    }, []);

    const isClassic = theme === 'classic';

    return (
        <div className="bg-white text-black min-h-screen">
            <div className="fixed top-6 right-6 print:hidden flex gap-4 z-50">
                <button onClick={onClose} className="bg-black text-white px-8 py-3 rounded-full hover:bg-gray-800 text-[10px] font-black uppercase tracking-widest shadow-2xl transition-all">Close Preview</button>
            </div>
            {dishes.map((dish, dishIdx) => (
                <div key={dish.id} className="w-full h-screen flex break-after-page page-break-always overflow-hidden bg-white" style={{ pageBreakAfter: 'always' }}>
                     <div className="w-1/2 h-full relative p-20 flex items-center justify-center">
                         <div className="responsive-image rounded-[4rem] overflow-hidden shadow-2xl border-[12px] border-gray-50 bg-gray-50">
                            <img src={dish.image} alt={dish.name} />
                         </div>
                     </div>
                     <div className="w-1/2 h-full p-24 flex flex-col justify-center">
                         <div className="text-[10px] uppercase tracking-[0.6em] mb-10 text-gray-400 font-black">{categories.find(c => c.id === dish.categoryId)?.name}</div>
                         <h1 className={`text-6xl mb-16 leading-none tracking-tighter ${isClassic ? 'font-serif italic font-bold' : 'font-black uppercase'}`}>{dish.name}</h1>
                         <div className="grid grid-cols-2 gap-16 mb-20">
                             <div className="border-l-4 border-gray-100 pl-8"><span className="block text-[10px] uppercase font-black text-gray-300 mb-2 tracking-widest">Energy</span><span className="text-4xl font-black">{dish.nutrition.calories} <span className="text-xl font-bold opacity-30">kcal</span></span></div>
                             <div className="border-l-4 border-gray-100 pl-8"><span className="block text-[10px] uppercase font-black text-gray-300 mb-2 tracking-widest">Protein</span><span className="text-4xl font-black">{dish.nutrition.protein}<span className="text-xl font-bold opacity-30">g</span></span></div>
                         </div>
                    </div>
                </div>
            ))}
        </div>
    );
}
